quests[29998] = { id = 29998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Dilemma des Bibliothekars", description = "Lehrensucher Steinschritt beaufsichtigt die gesamte Bibliothek des Tempels. In letzter Zeit scheint ihn und seine Arbeit etwas zu belasten.\n\nDa noch Tausende alter Folianten transkribiert werden müssen, sollte er voll konzentriert sein.\n\nWürdet Ihr dem südlichen Pfad zur Bibliothek folgen und herausfinden, was ihn plagt?", sourceObjective = "Sprecht mit Lehrensucher Steinschritt in der Bibliothek des Tempels.", completion = "Der Ältestenweise Ren-Zhu schickt Euch?\n\nNun gut. Ihr dürft mir helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[29999] = { id = 29999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Reiters Bindung", description = "Habt Ihr die jungen Schlangen auf dem Ausbildungsgelände gesehen?\n\nDie Kleinen haben oft Flausen im Kopf, und einige sind weggelaufen, um vor dem Training noch zu spielen.\n\nDie Herrin wird nicht erfreut sein, wenn sie das herausfindet.\n\nKönntet Ihr sie suchen und zu mir zurückbringen? Ich möchte nicht, dass sie Ärger bekommen.\n\nSie spielen gern im Freien, also sucht in den Höfen und bei den Pavillons nach ihnen.", sourceObjective = "Findet 4 verspielte Schlangen.", completion = "Ihr habt sie alle gefunden und zurückgebracht!\n\nSie scheinen Euch bereits zu mögen.\n\nVielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[30000] = { id = 30000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jadeschlange", description = "Ihr wollt der Jadeschlange eine Nachricht überbringen, nicht wahr?\n\n<Das kleine Mädchen sieht Euch mit schräg gelegtem Kopf fragend an.>\n\nIch schätze, es ist Zeit, dass Ihr vorgelassen werdet.", sourceObjective = "Hört der Jadeschlange zu.", completion = "Habt Ihr die Botschaft überbracht?", sourceObjectiveStatus = "unverified-source-field" }
quests[30001] = { id = 30001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mottenplage", description = "Motten sind in der Bibliothek eingefallen. Motten!\n\nJeder Bibliothekar, der seines Namens würdig ist, weiß, dass Motten nach den Bücherwürmern die größte Gefahr für Papier sind.\n\nWie sich herausgestellt hat, sind meine Assistenten Feiglinge, die sich vor Insekten fürchten.\n\nBitte, Ihr MÜSST mir helfen, diese Motten loszuwerden! Die Werke tausender Pandaren-Geschichtenerzähler müssen geschützt werden!", sourceObjective = "Vernichtet 8 gefleckte Motten.", progress = "Ich sehe von hier aus, wie die Motten das Papier fressen!", completion = "Ja, ja, danke! Ihr habt sie wunderbarerweise dezimiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[30002] = { id = 30002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Historische Seiten", description = "Das Allerschlimmste ist geschehen, {race}.\n\nWir. Haben. Bücherwürmer.\n\nDie Lage ist ernst. Alle Bücherwürmer in der Bibliothek müssen augenblicklich ausgelöscht werden, damit sie sich nicht noch weiter ausbreiten.\n\nWir müssen dieses Problem ausmerzen! Bitte untersucht die befallenen Bücher und zerquetscht jeden Bücherwurm, den Ihr findet.", sourceObjective = "Sucht in der Bibliothek nach befallenen Büchern und zerquetscht 12 Bücherwürmer.", completion = "Oh, großartig! Ich bin so erleichtert, dass wir die Katastrophe verhindern konnten.\n\nNein, nein, kommt bitte nicht näher. Ihr habt noch einige zerquetschte Überreste an den Schuhen kleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[30003] = { id = 30003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schein trügt" }
quests[30004] = { id = 30004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles an Ort und Stelle", description = "Ihr habt uns mehr geholfen, als Ihr Euch vorstellen könnt, {name}.\n\nIch weiß nicht, was wir getan hätten, wenn unsere kostbaren Schriftrollen verloren gewesen wären.\n\nBitte kehrt zum Ältestenweisen Ren-Zhu zurück und sagt ihm, dass in der Bibliothek alles in Ordnung ist.", sourceObjective = "Sprecht mit dem Ältestenweisen Ren-Zhu am Tempel der Jadeschlange im Jadewald.", completion = "Der Meister der Schriftrollen ist wieder bei der Arbeit?\n\nBemerkenswert. Euch ist gelungen, was vier Priester, die ich losgeschickt hatte, nicht vollbringen konnten.\n\nIch... Ich glaube, meine Kopfschmerzen klingen langsam ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[30005] = { id = 30005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Himmel erleuchten", description = "Mögt Ihr ein schönes Feuerwerk, <mein Herr/meine Dame>?\n\nIch jedenfalls schon! Früher haben wir damit Dämonen verscheucht, aber ich mag die schönen bunten Farben einfach!\n\nIch glaube, im Tempel liegen noch immer einige Abschussgeräte herum.\n\nWürdet Ihr für mich ein großes Feuerwerk entzünden? Das würde mich so glücklich machen!", sourceObjective = "Schießt 8 Feuerwerkskörper ab.", completion = "Hurra! Ich konnte das Feuerwerk von hier aus sehen!\n\nVielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30006] = { id = 30006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dunkelheit um uns herum", description = "Trotz unserer Bemühungen haben die Sha-Wesen die Siegel rings um den Haupttempel zerbrochen.\n\nWenn wir sie dort nicht zurückhalten können, wird sich ihre Dunkelheit im restlichen Jadewald ausbreiten.\n\nWir brauchen unverzüglich Eure Hilfe. Vernichtet alle Sha-Wesen, die Ihr seht. Sie dürften nicht schwer zu finden sein.", sourceObjective = "Vernichtet 15 Sha-Eindringlinge.", completion = "Danke, {name}. Jeder vernichtete Sha wendet das Blatt zu unseren Gunsten.", sourceObjectiveStatus = "unverified-source-field" }
quests[30007] = { id = 30007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Completed Arrival Phase" }
quests[30009] = { id = 30009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammeln in Fort Flotsch" }
quests[30011] = { id = 30011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Vision", description = "Bitte sagt dem Ältestenweisen Ren-Zhu, dass ich sofort mit der Arbeit beginnen werde.", sourceObjective = "Sprecht mit dem Ältestenweisen Ren-Zhu in der Nähe des Hofs des Tempels der Jadeschlange im Jadewald.", completion = "Großartig! Mir ist ein großer Stein vom Herzen gefallen, da ich jetzt weiß, dass der Wahrsager seine Meditationen wieder aufgenommen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[30015] = { id = 30015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgenblüte", description = "Blut und Donner! Meine Axt kann kaum noch stillhalten!\n\nWir werden nicht nach Orgrimmar zurückkehren, bis wir die gesamte, verdammte Allianz aus diesem Land vertrieben haben.\n\nIch werde die Eingeborenen selbst ausbilden, wenn's sein muss. Egal wie - wir werden dieses Land für die Ankunft der Horde vorbereiten.\n\nIn der Zwischenzeit hat mir ihr Anführer das hier für Euch gegeben - eine Karte und eine Nachricht in so einer hochtrabenden Schrift.\n\nTut also, was Ihr tun müsst. Aber beeilt Euch.\n\nDer Krieg rückt näher...", sourceObjective = "Sprecht mit Lehrensucher Cho in Morgenblüte.\n\nSprecht mit dem Flugmeister des Flotschhügels, um mitgenommen zu werden.\n\nBereitgestellter Gegenstand:", completion = "Seid gegrüßt, {name}!\n\nWillkommen in Morgenblüte, der Heimat meines Volkes.\n\nLeider muss ich es verlassen, denn die Arbeit eines Lehrensuchers ist niemals vollendet.\n\nFühlt Euch hier wie zu Hause. Eure Talente werden meinem Volk sicherlich von Nutzen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[30019] = { id = 30019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Bruch in der Mauer" }
quests[30020] = { id = 30020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenige Möglichkeiten" }
quests[30021] = { id = 30021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undurchdringbar" }
quests[30027] = { id = 30027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion des Eisenasts", description = "Zuallererst werdet Ihr eine Waffe benötigen, die Euren Fähigkeiten entspricht. Beschafft Euch einen Stab von einem der Waffenregale dort unten, bringt ihn zu mir und zeigt mir, dass Ihr auch wisst, wie man ihn richtig hält.", sourceObjective = "Nehmt Euch einen Schülerstab und legt ihn an.", completion = "Eine gute Waffe. Sie sollte Euren Bedürfnissen gerecht werden.\n\nLasst uns sehen, was Ihr damit anstellen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30028] = { id = 30028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getreiderettung", description = "Da Ihr auf dem Weg in Richtung Süden seid, könntet Ihr nicht versuchen, etwas von dem Getreide wiederzubringen, das mir diese Diebe gestohlen haben?\n\nWir haben Vögel und Geister gesehen, die mit ganzen Säcken unserer besten Erzeugnisse in die Felder östlich und südlich von hier geflohen sind.", sourceObjective = "Bringt Getreidefürst Kai 8 Säcke Getreide zurück.", progress = "Wegen dieser Vögel und Geister werden wir es nie schaffen, die Brauerei Sturmbräu ausreichend zu beliefern.", completion = "Vielen herzlichen Dank, Fremder. Heute war kein guter Tag, aber Ihr habt ihn zumindest erträglich für uns gemacht.\n\nBitte nehmt diese Belohnung. Ihr habt sie Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[30029] = { id = 30029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine miese Diebe", description = "Wir haben eine große Menge billiges Getreide gekauft. Leider war es mit Geistern verseucht.\n\nUnd ich HASSE diese Geister mit ihren kleinen Knopfaugen und ihrem ewigen Grinsen.\n\nIch möchte, dass Ihr diese Sache erledigt, ohne Aufsehen zu erregen. Kann ich Eure Dienste in Anspruch nehmen, um diese Getreidediebe diskret auszuschalten?", sourceObjective = "Tötet 8 gerissene Korndiebe.", completion = "Danke für Eure Hilfe, Fremder! Ab jetzt kommen wir hoffentlich allein klar.", sourceObjectiveStatus = "unverified-source-field" }
quests[30030] = { id = 30030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geistlos", description = "Um das gleich klarzustellen: Was geschehen ist, war ein Unfall. Ich hab' das nur für das GESCHÄFT gemacht!\n\nIch hatte ja keine Ahnung, dass eine Geisterinvasion droht oder dass einer von ihnen mein neues \"Pans Wunderwachstum\" fressen würde.\n\nUnd jetzt werden sie von einer nicht nur riesigen, sondern auch verdammt zornigen Bestie angeführt.\n\nWürdet Ihr sie erlegen, wenn ich Euch dafür bezahle?", sourceObjective = "Besiegt Kornan den Bierbaren.", progress = "Oje... Warum musste ich nur mit der natürlichen Ordnung der Dinge herumexperimentieren? Ich wollte doch nur, dass dieses Getreide schneller wächst und sich vermehrt.", completion = "Jetzt, wo die Sache ausgestanden ist, habe ich mir ein neues Mittel ausgedacht. Ich bin gespannt.\n\nDanke für Eure Hilfe. Hier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[30031] = { id = 30031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschmacksprobe", description = "Wenn Ihr schon einmal hier seid, könnt Ihr mir auch gerne helfen. Da ich keinen einzigen Tropfen Bier in meinem Leben getrunken habe, fühle ich mich gänzlich ungeeignet für diese Aufgabe.\n\nIhr solltet etwas von jedem der Getreide kosten. Schauen wir einmal, ob etwas davon süß genug für Onkel Chen ist.", sourceObjective = "Kostet vom reifen Getreide, hellen Getreide, frischen Getreide und vermälzten Getreide.", progress = "Nichts davon schmeckt süß genug! Woran liegt das?", completion = "Hm. Keines dieser Getreide ist das richtige. Onkel Chen ist ziemlich wählerisch.\n\nVielleicht weiß der Getreidefürst, wo ich etwas… Besonderes herbekomme.", sourceObjectiveStatus = "unverified-source-field" }
quests[30032] = { id = 30032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach dem süßen Getreide", description = "Ihr sucht nach einem süßen Getreide? Mein Vater sprach einmal von einer vermälzten Höhlengerste - die könnte es sein.\n\nWenn Ihr Euch der Gefahr stellen wollt, gibt es südlich von hier eine alte Höhle am Fuße der Windschneide.\n\nEs gibt sogar einen alten Aufzug, den mein Vater für seine Ausflüge in den Dschungel gebaut hat.\n\nIn der Höhle befindet sich ein Busch, der so alt ist wie meine Familie. Ihr könnt davon ein Getreidekorn abpflücken, das so süß schmeckt, dass es Eure Sinne berauschen wird.\n\nSeht Euch nur vor den Wächtern vor.", sourceObjective = "Findet die vermälzte Höhlengerste am Fuße der Windschneide.", progress = "Dieser Dschungel hört sich gruselig an.", completion = "Na DAS riecht aber einmal richtig gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[30033] = { id = 30033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion des Eisenasts", description = "Zuallererst werdet Ihr eine Waffe benötigen, die Euren Fähigkeiten entspricht. Beschafft Euch eine Zauberklinge und einen Fächer von einem der Waffenregale dort unten, bringt sie zu mir und zeigt mir, dass Ihr auch wisst, wie man sie richtig hält.", sourceObjective = "Nehmt Euch eine Schülerzauberklinge und einen Schülerfächer und legt sie an.", completion = "Eine gute Waffe. Sie sollte Euren Bedürfnissen gerecht werden.\n\nLasst uns sehen, was Ihr damit anstellen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30034] = { id = 30034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion des Eisenasts", description = "Zuallererst werdet Ihr eine Waffe benötigen, die Euren Fähigkeiten entspricht. Beschafft Euch eine Armbrust von einem der Waffenregale dort unten, bringt sie zu mir und zeigt mir, dass Ihr auch wisst, wie man sie richtig hält.", sourceObjective = "Nehmt Euch eine Schülerarmbrust und legt sie an.", sourceObjectiveStatus = "unverified-source-field" }
quests[30035] = { id = 30035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion des Eisenasts", description = "Zuallererst werdet Ihr Waffen benötigen, die Euren Fähigkeiten entsprechen. Beschafft Euch einen Streitkolben und ein Gebetsbuch von einem der Waffenregale dort unten, bringt sie zu mir und zeigt mir, dass Ihr auch wisst, wie man sie richtig hält.", sourceObjective = "Nehmt Euch einen Schülerstreitkolben und ein Schülergebetsbuch und legt sie an.", sourceObjectiveStatus = "unverified-source-field" }
quests[30036] = { id = 30036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion des Eisenasts", description = "Zuallererst werdet Ihr Waffen benötigen, die Euren Fähigkeiten entsprechen. Beschafft Euch ein Paar Dolche von einem der Waffenregale dort unten, bringt sie zu mir und zeigt mir, dass Ihr auch wisst, wie man sie richtig hält.", sourceObjective = "Nehmt Euch ein Paar Schülerdolche und legt sie an.", completion = "Eine gute Waffe. Sie sollte Euren Bedürfnissen gerecht werden.\n\nLasst uns sehen, was Ihr damit anstellen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30037] = { id = 30037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion des Eisenasts", description = "Zuallererst werdet Ihr Waffen benötigen, die Euren Fähigkeiten entsprechen. Beschafft Euch eine Axt und einen Schild von einem der Waffenregale dort unten, bringt sie zu mir und zeigt mir, dass Ihr auch wisst, wie man sie richtig hält.", sourceObjective = "Nehmt Euch eine Schüleraxt und einen Schülerschild und legt sie an.", completion = "Eine gute Waffe. Sie sollte Euren Bedürfnissen gerecht werden.\n\nLasst uns sehen, was Ihr damit anstellen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30038] = { id = 30038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lektion des Eisenasts", description = "Zuallererst werdet Ihr Waffen benötigen, die Euren Fähigkeiten entsprechen. Beschafft Euch eine Axt und einen Schild von einem der Waffenregale dort unten, bringt sie zu mir und zeigt mir, dass Ihr auch wisst, wie man sie richtig hält.", sourceObjective = "Nehmt Euch eine Schüleraxt und einen Schülerschild und legt sie an.", sourceObjectiveStatus = "unverified-source-field" }
quests[30039] = { id = 30039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel zu lernen", description = "Nun, da Eure Ausbildung begonnen hat, erhaltet Ihr Eure erste, recht simple Aufgabe: Sprecht mit Meister Shang Xi.", sourceObjective = "Sprecht mit Meister Shang Xi.", sourceObjectiveStatus = "unverified-source-field" }
