quests[30044] = { id = 30044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel zu lernen", description = "Nun, da Eure Ausbildung begonnen hat, erhaltet Ihr Eure erste, recht simple Aufgabe: Sprecht mit Meister Shang Xi.", sourceObjective = "Sprecht mit Meister Shang Xi.", sourceObjectiveStatus = "unverified-source-field" }
quests[30045] = { id = 30045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel zu lernen", description = "Nun, da Eure Ausbildung begonnen hat, erhaltet Ihr Eure erste, recht simple Aufgabe: Sprecht mit Meister Shang Xi.", sourceObjective = "Sprecht mit Meister Shang Xi.", sourceObjectiveStatus = "unverified-source-field" }
quests[30046] = { id = 30046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chens Vorsatz", description = "Wisst Ihr was? Ich will so nicht mehr weitermachen.\n\nIch werde diesem Onkel Gao zeigen, was ein richtiger Braumeister ist. Ich werde das beste Bier brauen, das er jemals getrunken hat, mit Zutaten, die er noch nie zuvor benutzt hat.\n\nIch bin Chen Sturmbräu, und ich bin der beste Braumeister, den es gibt.", sourceObjective = "Trefft Euch mit Chen Sturmbräu bei Halbhügel.", completion = "Jetzt geht's ans Brauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30047] = { id = 30047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chens Geschmacksprobe", description = "Onkel Chen wird begeistert sein. Oder... er sagt uns einfach nur, dass wir etwas finden müssen, das noch süßer schmeckt. So ist er halt.\n\nBringen wir einfach dieses Getreide zu ihm nach Halbhügel.", sourceObjective = "Kehrt zu Chen Sturmbräu zurück.", completion = "Ah! Na, das ist ja mal ein wunderbar vermälztes Getreide. Ihr beide habt wirklich gute Augen und Nasen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30048] = { id = 30048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Li Li und das Getreide", description = "Ich werde Euch meinen Brauplan verraten, {name}: Ich plane ein Kaiser-Starkbier herzustellen. Wenn man es richtig macht, sollte es dunkel, rauchig und mit hohem Alkoholgehalt ausgestattet sein.\n\n<Ein zweifelnder Blick schleicht sich in Chens Gesicht.>\n\nMir ist gerade etwas eingefallen... Ich habe Li Li gar nichts von meinen Plänen erzählt. Sie hat überhaupt keine Ahnung, welche Art Getreide sie mitbringen soll!\n\nKönntet Ihr mit ihr sprechen? Ich möchte, dass sie das süßeste Malzgetreide mitbringt, das sie finden kann.", sourceObjective = "Sprecht mit Li Li bei der Kaiserlichen Kornkammer im Tal der Vier Winde.", completion = "{name}? Was macht Ihr denn hier?\n\nAch so, Onkel Chen will süßes Malz? Kein Problem! Gehen wir doch einfach zur Verkostung.", sourceObjectiveStatus = "unverified-source-field" }
quests[30049] = { id = 30049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasserträger", description = "Könntet Ihr bitte Trübtrunk aufsuchen? Er braucht vielleicht Hilfe beim Rücktransport des Wassers.\n\nIch bin mir sicher, dass er Eure Muskelkraft gut gebrauchen kann, {class}.", sourceObjective = "Sprecht mit Trübtrunk am Goldfächer im Tal der Vier Winde.", completion = "{name}! Ihr wollt mir helfen?! Das ist aber wirklich nett von Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[30050] = { id = 30050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur die Harten kommen in'n Garten", description = "Ihr wollt, dass ich Euch den Hopfen einfach GEBE? Unglaublich! Das ist heute schon das dritte Mal, dass so <ein unverschämter/eine unverschämte:r> {race} wie Ihr Lebensmittel umsonst haben will!\n\nIhr braucht Lebensmittel? Dann müsst Ihr dafür arbeiten!\n\n<Sie drückt Euch eine Gießkanne in die Hand.>\n\nUnd jetzt wässert meine Pflanzen!", sourceObjective = "Befolgt Gärtnerin Frans Anweisung und wässert 60 ihrer Gemüsepflanzen.\n\nPflanzen kann man auch vom Rücken eines Reittiers aus wässern.", progress = "Wässert meine Pflanzen, Ihr fauler {class}!", completion = "Hm...\n\nGute Gartenarbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[30051] = { id = 30051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Große Wasserjagd", description = "Schaut, {name}: der Goldfächer. Ich hab' viele gute Dinge über das Wasser hier gehört. Und auch viele schlechte Dinge.\n\nIch hab' keine Ahnung, welches Wasser genau Chen braucht, also warum bringen wir ihm nicht ein paar Kostproben mit?\n\nAlso los, holen wir uns etwas Wasser.", sourceObjective = "Begleitet Trübtrunk zu den Wirbelnden Teichen des Goldfächers und helft ihm 30 Pfoten voll Wiesenwasser einzusammeln.\n\nWenn Ihr Trübtrunk aus den Augen verliert, könnt Ihr ihn neben der riesigen Banane im Goldfächer wiederfinden.", progress = "Dieser Sturmbräu behauptet, er wär' der beste Brauer weit und breit. Kann schon sein, aber bewiesen hat er's mir noch nicht.", completion = "Schaut doch mal was für 'ne hübsche Wassersammlung wir hier haben! Mit diesem magischen Wasser kann Chen sicherlich ein großartiges Bier brauen.\n\nOder ein Gebräu, das einen für die nächsten Monate an die Kloschüssel fesselt... Aber das werden wir wohl abwarten müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30052] = { id = 30052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unkrautvernichtung", description = "Ihr braucht etwas Hopfen? Davon habe ich draußen im Stall noch jede Menge. Ich kann Euch gern etwas davon geben - wenn Ihr mir helft, das Unkraut auf meinem Feld zu jäten.\n\nAlso los: hopf, hopf an die Arbeit!", sourceObjective = "Befreit Gai Lans Feld von 100 Exemplaren Unkraut.\n\nDas Unkraut könnt Ihr auch vom Rücken eines Reittieres aus jäten.", completion = "Im Jäten macht Euch niemand etwas vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[30053] = { id = 30053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hopfjagd", description = "Da sich Li Li um das Getreide und Trübtrunk um das Wasser kümmert, brauchen wir nur noch Hopfen und ein paar gute Holzfässer. Ich kümmere mich um die Fässer... Also müsstet Ihr etwas Hopfen besorgen.\n\nIch kenne mich mit dem Hopfen in diesem Land nicht aus, aber die Bauern in der Umgebung werden sicherlich etwas haben, was zum Brauen taugt. Versucht, so viel davon zu besorgen, wie Ihr könnt.", sourceObjective = "Bittet Gärtnerin Fran, Gai Lan und Den Lehmkrall um Hopfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30054] = { id = 30054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schluss jetzt, verfiddelt noch mal!", description = "Shed-Ling fressen zu viel.\n\nFressen Mung-Mungs Karotte. Fressen Mung-Mungs Kürbis. Mung-Mung will sie verscheuchen, aber die Knatzel beißen Mung-Mung in Schwanz und Fuß.\n\nSchluss jetzt, verfiddelt noch mal.\n\nDu kämpfst viel besser als Mung-Mung. Bring mir ihre Zähne. Dann ist Schluss mit fressen und beißen.", sourceObjective = "Sammelt 100 Zähne von Shed-Ling ein.", progress = "Du bringst mir die Zähne und Mung-Mung hat vielleicht etwas Hopfen für dich.", completion = "So viele Zähne! Vielleicht klebt Mung-Mung die zusammen und macht eine Harke daraus.", sourceObjectiveStatus = "unverified-source-field" }
quests[30055] = { id = 30055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmbräus Hopfnung", description = "Alle drei Bauern haben ihren Hopfen nach Halbhügel geliefert. Vielleicht solltet Ihr Chen aufsuchen, um sicherzustellen, dass er angekommen ist.", sourceObjective = "Kehrt zu Chen Sturmbräu in Halbhügel zurück.", completion = "Schaut Euch diese Menge Hopfen an! Und das ist sogar Qualitätsware.\n\nEs geht gut voran, {name}. Schon bald haben wir alle Zutaten, um mit dem Brauen zu beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30056] = { id = 30056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bauerstochter", description = "<Tapferer/Tapfere:c> {class}, wie gut, dass Ihr da seid! Meine Tochter ist verschwunden!\n\nUnd ich glaube, dass diese Shed-Ling sie in ihre kleine, stinkende Höhle verschleppt haben. Ich bin zu alt, um diese Shed-Ling zu bekämpfen, und mein Hofhelfer ist schon ganz erschöpft, weil er die Viecher den ganzen Morgen gejagt hat.\n\nKönntet Ihr bitte nach ihr suchen?", sourceObjective = "Findet Mina Lehmkrall.", completion = "Nein... nein... zurück... Ich will nicht...\n\nAber Moment, Ihr seid ja gar keine Karotte. Und auch kein Shed-Ling. Seid Ihr etwa hier, um mich zu retten?", sourceObjectiveStatus = "unverified-source-field" }
quests[30057] = { id = 30057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die orangene Bedrohung", description = "Diese Shed-Ling... Sie haben mich gezwungen, furchtbar, furchtbar absurde Dinge zu tun, die alle mit Karotten zu tun haben. Ihr glaubt ja gar nicht, mit wie vielen sie mich überhäuft haben.\n\nAber verschwenden wir besser keine Zeit: Holt mich hier raus!", sourceObjective = "Bringt Mina Lehmkrall zurück zu ihrem Vater.", completion = "Was soll das mit all diesen Karotten? Ich verstehe es einfach nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[30058] = { id = 30058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mottallus!", description = "Der werte Geselle Chu hat offensichtlich ein Monster erschaffen - den seidigen Tod mit Flügeln.\n\nMottallus.\n\nIhre Brut habt Ihr ja schon kennengelernt. Jetzt möchten wir Euch bitten, die Kreatur selbst zu bekämpfen.\n\nBitte, {class}, begebt Euch in die Grube, um den Köder auszulegen. Damit könnt Ihr die Bestie anlocken.\n\nUnsere Mottenkämpfer werden Euch bei Bedarf unterstützen. Allerdings scheint die Seide an ihnen besonders stark zu kleben. Wenn sie also in Bedrängnis geraten, könnte es sein, dass Ihr vielmehr ihnen helfen müsst.", sourceObjective = "Lockt Mottallus an und besiegt sie.", progress = "Habt Ihr die Bestie schon vernichten können?", completion = "In allem, was wir tun, streben wir nach Perfektion. Aber auf dem Weg dorthin werden uns viele Fehler unterlaufen.\n\nIch bin mir sicher, dass schon morgen wieder ein Tag voller Fehler auf uns wartet. Aber dennoch danken wir Euch für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[30059] = { id = 30059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mottenrebellion", description = "Oh... Oh, gut, <ein/eine:c> {class}! Könntet Ihr mir vielleicht helfen?\n\nIch habe im Zuge meiner Experimente zur Steigerung der Seidenproduktion eine Reihe widerlicher Monster erschaffen.\n\nAm Ende gab es sogar eine echte Mottenrebellion. Könntet Ihr vielleicht Euer Talent als {class} dafür einsetzen, ein paar dieser Mutanten zu vernichten?", sourceObjective = "Tötet 6 mutierte Seidenspinner und 8 winzige mutierte Seidenspinner.", progress = "Meister Goh hat mir immer gesagt, dass ich die Ruhe bewahren soll und dass Scheitern zum Lernen dazu gehört. Aber auf diese Art zu scheitern, ist gefährlich.\n\nEs könnte jemand zu Tode kommen dabei.", completion = "Es scheinen nicht mehr GANZ so viele verderbte Motten da draußen zu sein. Zumindest aber habt Ihr mir etwas Zeit verschafft, bevor ich wirklich großen Ärger bekomme.", sourceObjectiveStatus = "unverified-source-field" }
quests[30063] = { id = 30063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter den Masken", description = "Das Sha mag unaufhaltsam erscheinen, aber das ist es nicht.\n\nOffenbar bezieht es seine Macht aus seinen Masken. Werden eine Sha-Kreatur und die Maske getrennt, wird die Essenz der Kreatur zurück in ihr eigenes Reich verbannt.\n\nBringt mir intakte Masken, damit ich sie genauer untersuchen kann. Aber gebt Acht, denn das Sha wird sich gewiss nicht leichtherzig davon trennen.", sourceObjective = "Sammelt 8 Masken des Zweifels.", progress = "Bitte geht vorsichtig mit den Masken um. Wenn Ihr nicht Acht gebt, werden sie versuchen, Euch zu verschlingen.", completion = "Ich vermute, dass diese Masken dem Sha ermöglichen, eine physische Verbindung zu unserer Welt herzustellen.\n\nIch muss sie genauer untersuchen, wenn wir diese Kreaturen endgültig verbannen wollen.\n\nVielen Dank, {name}. Ich weiß Eure Hilfe sehr zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30064] = { id = 30064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung der Sutras", description = "Meine Adepten mussten ihre Studien unterbrechen, als die Sha-Invasion begann.\n\nLeider haben sie ihre Bücher auf dem Tempelgelände liegen gelassen. Diese unschätzbaren Werke müssen gerettet werden!\n\nIhr findet die Sutras in der Nähe der Ausbildungsarena und des Adeptenrings im Nordosten.", sourceObjective = "Sammelt 6 uralte Sutras.", progress = "Wie sehen die Sutras aus? Wurden sie beschädigt?", completion = "Vielen Dank! Ich bin so erleichtert, dass diese Texte in Sicherheit sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[30065] = { id = 30065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfeile des Glücks", description = "Unser Kriegsmaterial geht zur Neige, und wir benötigen vor allem weitere Pfeile.\n\nUnsere Schlangenreiter sind geübte Schützen, doch ohne Munition können sie nicht viel ausrichten.\n\nWir brauchen jemanden, der sich auf die Schlachtfelder wagt und unbeschädigte Pfeile sammelt, um unsere Vorräte aufzustocken.\n\nJeder Pfeil, den Ihr findet, wird von Nutzen sein.", sourceObjective = "Sammelt 8 Pfeile des Verteidigers.", progress = "Konntet Ihr einige Pfeile finden?", completion = "Diese Pfeile sind in einem guten Zustand. Sie werden ihren Zweck erfüllen.\n\nGut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30066] = { id = 30066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgene Macht", description = "Unsere Tempelverteidiger kämpfen seit Stunden ohne Unterlass. Sie werden gewiss langsam müde.\n\nIch werde Euch Mantras geben, die Ihr unseren Kämpfern bringen könnt.\n\nLasst Euch von den Schriftstücken nicht täuschen, diese alten Schriften enthalten Worte von unsagbarer Macht.", sourceObjective = "Bringt alte Mantras zu 6 Wächtern oder Adepten von Yu'lon.", completion = "Das Sha ist Legion, und wir sind nur wenige. Aber davon lassen wir uns nicht einschüchtern.\n\nDanke für Eure Hilfe beim Schutz unserer Heimat, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30067] = { id = 30067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatten des Zweifels", description = "Eine der großen Manifestationen des Sha ist im Süden erschienen.\n\nSie versucht, ein altes Relikt, die Glocke der Tausend Flüsterworte, zu zerstören.\n\nDiese Glocke ist in der Geschichte des Tempels noch nie geläutet worden, da sie ein altes Instrument der Macht sein soll.\n\nBitte besiegt diesen Dämonen auf der Stelle! Wir müssen dieses Relikt retten!", sourceObjective = "Besiegt den Schatten des Zweifels.", progress = "Die Glocke soll die Stimmen von eintausend gefallenen Tempelpriestern enthalten.", completion = "Ihr habt uns gerettet. Vor welchem Schicksal, das mag ich mir gar nicht ausmalen...", sourceObjectiveStatus = "unverified-source-field" }
quests[30068] = { id = 30068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammen der Leere", description = "Seht Ihr die wilden Flammen, die rings um den Tempel lodern?\n\nJe größer unsere Zweifel, desto heftiger brennen sie. Wenn wir nichts unternehmen, werden sie den ganzen Tempel verschlingen.\n\nWir haben eine letzte Hoffnung.\n\nFliegt auf einer unserer Kriegsschlangen zu den reinen Wasserquellen, und löscht das Feuer mit Wasser aus den Becken.", sourceObjective = "Fliegt mit Eurer Kriegsschlange zu reinem Quellwasser und löscht dann 6 Flammen der Leere mit dem Wasser aus ihrem Maul.", progress = "Dieses Feuer brennt wie nichts sonst auf dieser Welt.", completion = "Ihr habt uns beim Löschen des Feuers sehr geholfen. Danke für Eure Mühe.", sourceObjectiveStatus = "unverified-source-field" }
quests[30069] = { id = 30069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Plan überlebt den Feindkontakt", description = "Schnell und ruhig, genau so geht der SI:7 am liebsten vor. Zumindest war es so geplant.\n\nRell Nachtwind ist schon im Inneren von Garrosh'ar und sucht nach Hinweisen auf Anduin und Taylor, da drinnen wird es aber heiß und er braucht Unterstützung.\n\nKämpft Euch an diesen Hunden vorbei und findet Rell!", sourceObjective = "Tötet 6 Grunzer und 4 Kupplungsschmierer von Garrosh'ar.", progress = "Hier wimmelt es nur so von Soldaten der Horde. Mit so vielen im Nacken kommen wir nicht zu ihrem Anführer durch.", completion = "Gute Arbeit! Falls Ihr Euer Abenteurerdasein jemals an den Nagel hängen solltet, gibt es beim SI:7 bestimmt einen Platz für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[30070] = { id = 30070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall von Ga'trul", description = "Also schön, <Kumpel/Mädel>. Wir haben dieser Hexenmeisterarmee genügend Stöße verpasst... jetzt ist es Zeit, ihr den Kopf abzuhacken.\n\nGa'trul ist dort hinten, in der großen alten Tempelruine. Verdrescht ihn ordentlich, damit die Horde ihren letzten Pfeiler hier in Pandaria verliert.", sourceObjective = "Tötet Ga'trul.", completion = "Sha...\n\nIn fremden Gefilden gegen die Horde zu kämpfen, ist schwierig genug.", sourceObjectiveStatus = "unverified-source-field" }
quests[30072] = { id = 30072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So geht Seide", description = "Hättet Ihr Lust, für einen Tag <ein Seidenmeister/eine Seidenmeisterin> zu sein?\n\nDann braucht Ihr zunächst einmal Maulbeerblätter. Die findet Ihr in unserem Maulbeerbuschgarten im Nordwesten.\n\nUnd wenn Ihr die habt, verfüttert Ihr sie an eine hungrige Seidenraupe in unserer Grube im Westen.\n\nUnd schließlich müsst Ihr noch etwas Rohseide aus unserer Fertigungshütte auf der Südseite unseres Hofes besorgen.\n\nViel Spaß!", sourceObjective = "Sammelt Maulbeerblätter, füttert 5 hungrige Seidenraupen und besorgt Rohseide.", progress = "Habt Ihr alles gefunden? Habt Ihr Euch die Fertigung genau angeschaut?", completion = "Sehr gute Proben. Ich werde dafür sorgen, dass sie in die richtigen Hände gelangen. Hier, dieser kostenlose Artikel aus unserem Sortiment ist für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[30073] = { id = 30073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das kaiserliche Gebräu", description = "Wir haben alles, was wir brauchen. Jetzt sollten wir mit dem Brauen beginnen.\n\nPasst gut auf, {name}... Vielleicht könnt Ihr noch etwas lernen.", sourceObjective = "Bleibt vor Ort und helft Chen Sturmbräu, sein Gebräu herzustellen.", progress = "Bier lässt sich nicht einfach in drei Sekunden herstellen, {name}. Selbst wenn mein Name Chen Sturmbräu lautet.", completion = "Danke, dass Ihr so lange gewartet habt. Ihr seid ebenso geduldig wie mutig.", sourceObjectiveStatus = "unverified-source-field" }
quests[30074] = { id = 30074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klopf, klopf", description = "Und jetzt auf zur Brauerei Sturmbräu! Höchste Zeit, dass ich mal wieder die anderen Sturmbräus zu sehen bekomme... Und wie kann man ein Wiedersehen besser feiern als mit ein paar Krügen Bier?\n\nIhr wisst doch, wo die Brauerei ist, oder? Folgt einfach dieser Straße nach Westen, Ihr könnt sie nicht verfehlen. Aber natürlich könnt Ihr auch mit uns kommen. Wir werden jeden Augenblick aufbrechen.", sourceObjective = "Trefft Euch mit Chen Sturmbräu am Eingang der Brauerei Sturmbräu.", completion = "Die Tür ist... verbarrikadiert?", sourceObjectiveStatus = "unverified-source-field" }
quests[30075] = { id = 30075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg frei", description = "Seht Ihr das? Shed-Ling, Ho-zen und Wassergeister... die alle aus den Türen und Fenstern der Brauerei herausströmen! Was zum Teufel ist da drinnen los!?\n\nEs gibt noch einen anderen Eingang, auf der Ostseite der Brauerei. Ich werde dorthin laufen und da mal nachsehen. In der Zwischenzeit könnt Ihr vielleicht diese Kreaturen beseitigen. Es gibt wirklich nichts Schlimmeres als betrunkene Ho-zen.", sourceObjective = "Tötet 10 bierbenebelte Ho-zen oder schelmische Shed-Ling.", completion = "Ich hab' genug von dieser Brauerei. Vielleicht sollten wir beide da einfach reingehen und mal so richtig aufräumen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30076] = { id = 30076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das beste Wasser", description = "Ich hab' viele verrückte Geschichten über diese Brauerei hier gehört und immer geglaubt, dass sie nicht wahr sind... bis ich diesen riesigen Ho-zen gesehen habe.\n\nUnd dann fragte ich mich, ob an den Geschichten vielleicht doch was dran wäre. Ich hab' zum Beispiel von Wassergeistern gehört, die frei in der Brauerei herumlaufen und Krawall veranstalten. Ihre Körper BESTEHEN AUS WASSER.\n\nMit ihrem Wasser könnte man sicher ein leckeres Bierchen brauen. Würdet Ihr mir vielleicht etwas davon mitbringen, wenn Ihr ihnen begegnet?", sourceObjective = "Sammelt 3 Geistwasseressenzen ein.", progress = "Das wird fantastisch. Das ist genau wie Bierbrauen - nur, dass ich statt normalem Wasser diese Wassergeistkörper verwende.", completion = "Sieht für mich wie ganz gewöhnliches Wasser aus. Kaum zu glauben, dass es der Körper einer echten, sich bewegenden Kreatur gewesen sein soll.\n\nIch kann's kaum erwarten, daraus Bier zu brauen und es zu probieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[30077] = { id = 30077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fasswerfen", description = "Dieser riesige Ho-zen ist ja wirklich unfassbar! Er wirft mit diesen Fässern einfach nur so um sich!\n\nMit Fässern!\n\nUnd er scheint so gut wie allen Pandaren, die draußen vor der Brauerei gearbeitet haben, eines übergestülpt zu haben. An Eurer Stelle würde ich denen da raushelfen. Dafür könnt Ihr endlich mal Eure ganze Muskelkraft verwenden.\n\nWir sind auf dem Weg zum Hintereingang der Brauerei, im Osten. Kommt am besten auch dahin!", sourceObjective = "Befreit 7 abgefasste Pandaren.", completion = "Was genau fasziniert Affen bloß immer so an Fässern?", sourceObjectiveStatus = "unverified-source-field" }
quests[30078] = { id = 30078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hausputz", description = "So, {name}, jetzt habe ich wirklich die Nase voll davon.\n\nWenn sich KEINER einen Deut um diese Brauerei schert, werden wir sie für immer verlieren. Und es steckt viel zu viel Familiengeschichte - und Bier - da drinnen, um das zu riskieren.\n\nAlso werden wir durch die Hintertür einbrechen. Ihr, Li Li, Trübtrunk und ich.\n\nDas wird eine echte Massenschlägerei geben.\n\nSagt mir bitte, wenn Ihr bereit seid.", sourceObjective = "Besiegt Eddy, Jooga und den sprudelnden Bierlementar.", completion = "Schaut Euch um, draußen ist es schon viel ruhiger. Die Brauerei brauchte nur jemanden, der mit starker Hand aufräumt.\n\nEs wird eine Weile dauern, das alles hier wieder auf Vordermann zu bringen, aber das macht mir nichts aus.\n\nImmerhin... dies ist mein Zuhause.", sourceObjectiveStatus = "unverified-source-field" }
quests[30079] = { id = 30079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist mit Zhus Wacht los?", description = "Pandaren heißen Reisende immer mit offenen Armen willkommen - und mit offenen Fässern! Aber diese Stadt voller Trottel!\n\nJeder so damit beschäftigt, übellaunig zu sein, dass niemand je mit Ken-Ken spricht!\n\nKönnt Ihr in der Stadt nach einem suchen, der mit uns spricht? Vielleicht normale Pandaren sich nur in den Häusern verstecken?", sourceObjective = "Sprecht in Zhus Wacht mit Einwohnern und sucht jemanden, der sich mit Euch unterhalten möchte.", completion = "Nur eine Pandadame, die nicht verrückt ist? Das schlimmer als Ken-Ken gedacht hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[30080] = { id = 30080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Yi-Mo", description = "Mein Neffe Yi-Mo war immer schon etwas depressiv. Als die Welle der Verzweiflung über der Stadt zusammenschlug, traf es ihn härter als die meisten anderen. Tagelang saß er nur herum und wollte nichts essen. Er starrte nur in die Ferne.\n\nJetzt ist er in Richtung der Klippen nordöstlich von hier davongelaufen, dorthin, wo die Donnervögel nisten und jagen.\n\nKönnt Ihr ihn bitte suchen, {class}?", sourceObjective = "Sucht nach Yi-Mo Langbraue irgendwo nordöstlich von Zhus Wacht.", progress = "<Yi-Mo stößt einen langen Seufzer aus.>", completion = "Lasst mich raten: Meine Tante hat Euch geschickt?", sourceObjectiveStatus = "unverified-source-field" }
quests[30081] = { id = 30081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Materia Medica", description = "In Ordnung, Ken-Ken ganz sicher, er weiß, was mit Pandaren nicht stimmt! Habe altes, altes Ho-zen-Heilmittel, das hilft.\n\nMuss Honig, Fischöl und Salz mischen. Ken-Ken hat eine Menge Bienenstöcke in den Bäumen rund um die Stadt gesehen, und in den ausgetrockneten Teichen müssen noch Fische liegen.\n\nDann fehlt noch Salz... Mei weiß vielleicht, wo wir etwas finden.", sourceObjective = "Sammelt 4 Stücke einer Honigwabe, 4 glitschige Matschflosser und 4 salzige Kerne in der Zhu-Provinz.", progress = "Kann nicht glauben, dass Ken-Ken da nicht früher dran gedacht hat. Es ist die EINE Sache, die seinen ganzen Tag ruinieren kann...", completion = "Pandaren leiden an Grusel-Knatzel!\n\nKnatzel erschrecken manchmal und wollen nicht rauskommen. Arme, flauschige Mufpansel müssen bald explodieren!\n\nDas hier wird sie rauslocken. Das macht Pandaren sicher fröhlich!\n\nWie Omma immer gesagt hat: Wer nicht GEHEN kann, kann nicht WERFEN!", sourceObjectiveStatus = "unverified-source-field" }
quests[30082] = { id = 30082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopf hoch, Yi-Mo", description = "Seit dieser Sturm begann, bin ich einfach nur... müde.\n\nNicht körperlich... nein. Es ist, als ob meine Seele erschöpft wäre. Wertlos. Hoffnungslos. Ich denke, so fühlt man sich, wenn man von seiner Gefährtin für jemanden mit runderem Leib verlassen wird. Aber ich hatte noch nie eine Gefährtin, also woher soll ich das wissen?\n\nWie kann ich behaupten, überhaupt etwas zu wissen? Ich bin für alle wertlos, außer für diese Donnervögel. Zumindest gebe ich ein gutes Mahl für sie ab.\n\n<Yi-Mo seufzt tief und starrt weiter in den Himmel. Es sieht nicht so aus, als ob er bald irgendwo hingehen würde.>", sourceObjective = "Bringt Yi-Mo Langbraue zurück nach Zhus Wacht.", completion = "Ich kann nicht glauben, dass er das wirklich vorhatte... Diese Verzweiflung ist schlimmer, als ich je gedacht hätte.\n\nIch kann Euch nicht genug danken, dass Ihr ihn zurückgebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30083] = { id = 30083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung der Provinz", description = "Unser Einfluss auf die Provinz wird schwächer. Jetzt haben sich schon Saurok aus der Wildnis in der Höhle gleich nördlich der Stadt eingenistet.\n\nDa die meisten unserer Jäger in Tränen liegen, spazieren die Saurok einfach hier rein, als wären sie hier zu Hause. Sie bedienen sich nach Lust und Laune!\n\nIch möchte ein klares Signal aussenden: Es ist gesünder, sich nicht mit Zhus Wacht anzulegen!\n\nWerdet Ihr <mein Bote/meine Botin> sein?", sourceObjective = "Tötet 10 Saurok oder Kräuterkundige der Wildschuppen in der Provinz Zhu.", completion = "Danke, {name}. Damit dürftet Ihr diesen Wilden ihre Grenzen aufgezeigt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[30084] = { id = 30084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grenzlande", description = "Feuer erweisen sich als überraschend effektiv dabei, Bestien zu entmutigen, die Wildnis zu verlassen. Wir verfügen über drei davon an der südwestlichen Grenze, die wir normalerweise ununterbrochen am Brennen halten.\n\nEs war aber seit Tagen niemand dort, sodass die Feuer niedergebrannt sein müssen. Es ist nur eine Frage der Zeit, bis die Wildnis zurückkommt und das Land übernimmt, das wir seit Jahrhunderten gesichert haben.\n\nEntzündet bitte die Feuer wieder. Sie sind für die Sicherheit der Provinz äußerst wichtig, zudem sind sie Denkmäler für die Begründer unserer Lebensweise.", sourceObjective = "Entzündet die Gedenkflamme von Zhu, die Gedenkflamme von Rin und die Gedenkflamme von Po entlang der südwestlichen Grenze der Zhu-Provinz.", completion = "Danke, {name}.\n\nDie Zhu-Provinz dient als Korridor von der oberen Ebene des Tals hinunter zum Meer.\n\nDie Sicherheit der Provinz erfordert tägliche Anstrengungen bei der Erhaltung der Grenze zur wilden Krasarangwildnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[30085] = { id = 30085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Brauerei", description = "Wir müssen herausfinden, was in dieser Brauerei vor sich geht, {name}!\n\nWir haben uns zwar vielleicht der größeren Schädlinge entledigt, aber ich bin mir sicher, dass es da wo die herkommen noch mehr gibt. Sammelt ein paar Eurer Freunde um Euch und trefft mich im Inneren!", sourceObjective = "Sprecht mit Chen Sturmbräu in der Brauerei Sturmbräu.", completion = "Ihr seid gekommen! Großartig!\n\nIch freue mich schon darauf, erneut an Eurer Seite zu kämpfen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30086] = { id = 30086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach dem verborgenen Meister", description = "Oh, hallo. Sucht Ihr nach dem Besitzer dieser Einrichtung? Dann geht zu dem Pandaren oben an der Treppe. Ich bin bloß zu Besuch hier... genau wie Ihr.\n\nWenn Ihr mich nun entschuldigen würdet, meine Freunde und ich haben etwas zu besprechen. Wir können uns danach wieder unterhalten.", sourceObjective = "Hört Euch das Gespräch zwischen Xiao und seinen Freunden an.", completion = "Habt Ihr etwa zugehört? Keine Sorge, das macht mir nichts aus. Ihr könnt Euch gern an der Suche nach dem verborgenen Meister beteiligen.\n\nAber wenn Ihr ihn finden solltet, würde ich es zu schätzen wissen, wenn Ihr wieder hierherkommt und es uns mitteilt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30087] = { id = 30087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Kung Fu-Intro", description = "Oh, hallo. Sucht Ihr nach dem Besitzer dieser Einrichtung? Dann geht zu dem Pandaren oben an der Treppe. Ich bin bloß zu Besuch hier... genau wie Ihr.\n\nWenn Ihr mich nun entschuldigen würdet, meine Freunde und ich haben etwas zu besprechen. Wir können uns dann danach wieder unterhalten.", sourceObjective = "Hört Euch das Gespräch zwischen Xiao und seinen Freunden an.", sourceObjectiveStatus = "unverified-source-field" }
quests[30088] = { id = 30088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warum so ernst?", description = "Schön, funktioniert nicht. Gut... Ken-Ken freut sich! Aber Pandaren immer noch traurig...\n\nWir versuchen anderes altes Ho-zen-Heilmittel - diesmal gehen wir noch weiter zurück als Omma, viel, VIEL weiter zurück zu alten Zeiten. Ho-zen machen das manchmal immer noch... meistens auf Feiern.\n\nKen-Ken hat Holz zu bearbeiten - Bringt ihm Zähne! Nicht Eure. Große Zähne wie von Panther!\n\nOh, und etwas Farbe! Mei weiß vielleicht, wo Ihr suchen könnt.", sourceObjective = "Sammelt 18 riesige Pantherreißzähne und 1 Pigmentkrug aus der Provinz Zhu.", progress = "<Ken-Ken arbeitet hart dran, etwas aus der Baumrinde zu schnitzen.>\n\nDas wird toll, Ihr werdet schon sehen.", completion = "Gerade rechtzeitig! Komplett fertig... Seht!\n\n<Ken-Ken hält eine geschnitzte Holzmaske mit einem albernen Gesicht hoch.>\n\nJetzt noch ein paar Feinheiten und wir haben eine garantiert funktionierende SPASSMASCHINE!", sourceObjectiveStatus = "unverified-source-field" }
quests[30089] = { id = 30089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Brett vor dem Kopf", description = "Also... DAS kam unerwartet!\n\nWas ich noch sagen wollte, Ken-Ken hat sich erinnert, warum Ho-zen Maske zuerst benutzt haben...\n\nDie Legende vom Affenkönig sagt, er habe eine Maske benutzt, um den alten Pandarenkaiser Shaohao zu heilen, als er zu traurig war, um seine Leute zu führen. Dann haben sie Maske begraben - mit seiner ganzen Traurigkeit - im Boden.\n\nWir sollten die Maske bei mehr Pandaren benutzen, aber anstatt Traurigkeit im Boden zu begraben, werden wir ihr IN DEN HINTERN TRETEN.\n\nMachen wir es so, {name}!", sourceObjective = "Setze Ken-Kens Maske ein, um 8 bedrückte Wächter von Zhu in Zhus Wacht zu heilen.", progress = "Das muss die Traurigkeit vom Imperator sein, die zurückkommt! Das ist aaaaalte Traurigkeit.\n\nKen-Ken wettet, {race}-Traurigkeit wird mit Alter stärker, wie {race}-Schnaps.", completion = "Wir retten Pandaren, aber das Land immer noch traurig... Seht, Regen hört gar nicht auf!\n\n<Ken-Ken schüttelt seine kleinen Fäuste gen Himmel.>\n\nIn wie viele Hintern müssen wir treten, bevor in dieser Stadt wieder alles im Lot ist?!\n\n<Der Himmel verfinstert sich als Antwort darauf.>", sourceObjectiveStatus = "unverified-source-field" }
quests[30090] = { id = 30090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zhus Verzweiflung", description = "Hmm... Ist das da hinten der kleine Yi-Mo?\n\n<Ken-Ken blinzelt gegen den zunehmenden Regenguss.>\n\nIst er! Er ist am Brunnen und er sieht gar nicht gut aus.\n\nKen-Ken hat ein ganz schlechtes Gefühl...", sourceObjective = "Exorziert das Sha der Verzweiflung aus Yi-Mo Langbraue in Zhus Wacht.", completion = "Wir haben hier und heute gute Arbeit geleistet, {name}.\n\nDas Kloster sagt uns immer, wir sollen einen Ort besser zurücklassen, als wir ihn vorfanden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30091] = { id = 30091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tränen von Pandaria", description = "Dies alles hat bei unseren Teichen angefangen. Das ganze Wasser hat sich an einem einzigen Tag in die Erde zurückgezogen. Als alles Wasser aus den Teichen verschwunden war, begann es vom Himmel herabzufallen.\n\nTrotz endloser Regengüsse füllen sich die Teiche nicht. Es ist, als ob das Land selbst einen Durst hätte, der nicht gestillt werden kann.\n\nNun entspringen den Teichen schreckliche Manifestationen der Verzweiflung. Elementare aus dem Wasser des Himmels und dem Salz der Erde: die Tränen von Pandaria.", sourceObjective = "Tötet 12 weinende Schrecken in der Zhu-Provinz.", progress = "Ich weiß nicht, warum das passiert, aber ich bin mir sicher, dass alles mit diesen Elementaren angefangen hat.", completion = "Danke, {class}.\n\nEs ist Zeit, dass wir unser Land diesem Fluch entreißen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30092] = { id = 30092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Spitzel von Gilneas", description = "Wenn Ihr Euch mir anschließen und die untergetauchten schwarzen Drachen abschlachten wollt, behauptet Euch und tötet Hiram Altair. Er versammelt eine Armee in Gilneas.\n\nBisher ist uns nicht geglückt, an seinen Wachen vorbeizukommen, aber wir haben einen Mann vor Ort, der ihn nicht aus den Augen lässt. Zazzo Glitzerfinger, ein handwerklich geschickter arkaner Magier, der darauf wartet, dass wir mit ihm außerhalb der Ruinen der gilnearischen Hauptstadt Kontakt aufnehmen.\n\nFindet ihn, er wird Euch den Weg weisen.", sourceObjective = "Macht Zazzo Glitzerfinger nahe der Ruinen von Gilneas in Gilneas ausfindig.", completion = "Rabenholdt hat Euch gesandt? Ich hoffe, dass Ihr ein besserer Attentäter seid, als die anderen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30093] = { id = 30093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Altair assassinieren", description = "Seit Tagen schon herrscht Chaos in der Stadt. Hiram Altair, als Gilneer verkleidet, hat die meisten dieser Hunde mit seinem eigenen drakonischen Blut infiziert. Sogar die Verlassenen tun sich schwer, ihn zu überwinden.\n\nEinzig ein sauberer Mord kann das beenden!\n\nDie Brücke hinter mir ist relativ unbewacht. Begebt Euch über den Händlerplatz Richtung Süden - dort werdet Ihr Altair mitten im Militärviertel finden.\n\nIch werde Euch im Auge behalten und eingreifen, sollten Probleme auftauchen.\n\n...Und es WIRD Probleme geben!", sourceObjective = "Schleicht Euch in die Ruinen von Gilneas und tötet Hiram Altair im Militärviertel.", completion = "Altair ist vernichtet. Die Gilneer, die ihm gefolgt sind, sind jetzt allein, vorausgesetzt, dass sie nicht an seinem verderbten Drachenblut sterben.\n\nDoch egal, was mit ihnen geschieht, sie stellen nicht länger eine Gefahr für uns dar.", sourceObjectiveStatus = "unverified-source-field" }
quests[30094] = { id = 30094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Endzeit", description = "Nozdormu, der bronzene Drachenaspekt, hat die Champions der Horde um Hilfe gebeten. Auch Ihr wurdet auserwählt. Mehr kann ich Euch nicht sagen.\n\nEs ist äußerst ungewöhnlich, dass mein Meister sterbliche Wesen um Hilfe bittet, aber ich vermute, dass die Zeit alles verändert... sogar den Aspekt der Zeit selbst.\n\nEr wartet auf Euch in der Endzeit, in ferner Zukunft. Ich kann Euch helfen, dorthin zu gelangen, wenn Ihr es wünscht.", sourceObjective = "Sprecht mit Nozdormu in der Endzeit.", completion = "{name}, Ihr seid angekommen. Das ist gut. Ich möchte mich entschuldigen, dass ich Euch unter so verdächtigen Umständen zu diesem seltsamen Ort gebracht habe.\n\nIch habe einen guten Grund dafür.\n\nWir werden Todesschwinge töten. Und ich brauche Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[30095] = { id = 30095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Endzeit", description = "Nozdormu, der bronzene Drachenaspekt, hat die Champions der Allianz um Hilfe gebeten. Auch Ihr wurdet auserwählt. Mehr kann ich Euch nicht sagen.\n\nEs ist äußerst ungewöhnlich, dass mein Meister sterbliche Wesen um Hilfe bittet, aber ich vermute, dass die Zeit alles verändert... sogar den Aspekt der Zeit selbst.\n\nEr wartet auf Euch in der Endzeit, in ferner Zukunft. Ich kann Euch helfen, dorthin zu gelangen, wenn Ihr es wünscht.", sourceObjective = "Sprecht mit Nozdormu in der Endzeit.", completion = "{name}, Ihr seid angekommen. Das ist gut. Ich möchte mich entschuldigen, dass ich Euch unter so verdächtigen Umständen zu diesem seltsamen Ort gebracht habe.\n\nIch habe einen guten Grund dafür.\n\nWir werden Todesschwinge töten. Und ich brauche Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[30096] = { id = 30096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murozond", description = "Wenn wir Todesschwinge töten wollen, benötigen wir die Macht der Drachenseele. Um die Drachenseele zu erhalten, müsste ich Euch zur Zerschlagung zurückbringen, zehntausend Jahre in die Vergangenheit… aber dieser Zeitpfad ist mir versperrt.\n\nDas Monster, das uns den Weg zu diesem Zeitpfad blockiert, heißt Murozond. Er muss hier und jetzt, in dieser verqueren Zukunft, getötet werden, damit wir unsere Mission fortsetzen und Todesschwinge aufhalten können.\n\nDeshalb seid Ihr hier, {name}.", sourceObjective = "Tötet Murozond.", completion = "Murozond ist tot. Die Pfade der Zeit stehen mir wieder offen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30097] = { id = 30097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfsarchivar", description = "So wie ich das sehe, möchtet Ihr diese Zukunft also abwenden. Nun, wenn dem wirklich so ist, müssen wir Daten aus dem Zeitstrang archivieren, bevor sie verloren sind.\n\nWir denken, dass die interessantesten und wertvollsten aller Elemente dieser Zukunft die mächtigen \"Echos\" sind, die im Bronzedrachenschrein widerhallen.\n\nNehmt dieses Gefäß an Euch, um die Echos verstummen zu lassen. Ein Teil ihrer Energie wird vom Bronzenen Drachenschwarm eingelagert.", sourceObjective = "Tötet zwei der Echos in der Endzeit und gebt Alurmis Behältnis die Gelegenheit, ihre Informationen zu archivieren.", progress = "Nozdormu handelt in Eile, was er gewöhnlicherweise nicht tut.\n\nAn normalen Tagen würde ich die Archivierung gründlicher durchführen, doch aufgrund dieser Umstände können wir nur einen Teil unserer Funde ins Archiv aufnehmen... und wir müssen Söldner wie Euch anheuern.", completion = "<Alurmi nimmt Euch das Behältnis ab.>\n\nVon hier an werde ich mich darum kümmern. Sie müssen sorgfältig benannt, dokumentiert und eingelagert werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30098] = { id = 30098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Brunnen der Ewigkeit", description = "Wir müssen uns beeilen, bevor die übriggebliebenen ewigen Agenten einschreiten. Zeit ist kostbar.\n\nIch werde Euch jetzt aus Eurer fernen Zukunft weit zurück in die Vergangenheit bringen... zum Krieg der Ahnen. Unser Ziel ist die Drachenseele, ein Artefakt mit immenser Macht... genug, um Todesschwinge zu besiegen und seine Herrschaft über die Gegenwart zu beenden.", sourceObjective = "Sprecht mit Nozdormu am Brunnen der Ewigkeit.", completion = "Lasst uns fortfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[30099] = { id = 30099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Scharen", description = "Zwischen uns und der Drachenseele liegt eine Dämonenlegion. Bevor wir weiterziehen, müssen wir sie erledigen.\n\nWenn meine Zeiteinschätzung stimmt - wie normalerweise - sollte in Bälde ein Nachtelf mit Namen Illidan Sturmgrimm unseren Weg kreuzen. Er wird uns zweifelsohne von großem Nutzen sein bei der Dämonenjagd.\n\nHelft Illidan dabei, die Dämonenportale zu deaktivieren, tötet dann Peroth'arn, den Dämonenanführer.", sourceObjective = "Deaktiviert die drei Dämonenportale und erschlagt dann Peroth'arn.", completion = "Gut. Wir marschieren weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[30100] = { id = 30100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Selbstherrlichen", description = "Königin Azshara und ihre königliche Wache befinden sich vor uns. Wir können es uns nicht erlauben, dass irgendetwas unserem Plan in die Quere kommt. Also werden wir sie angreifen, bevor sie die Gelegenheit hat, sich einzumischen.\n\nEs ist eher unwahrscheinlich, dass Ihr Königin Azshara heute tötet; es existieren nur wenige verständliche Zeitstränge entlang dieses Pfades. Betrachtet es als einen Sieg, wenn Ihr es schafft, kurzzeitig ihre Aufmerksamkeit zu erringen.", sourceObjective = "Beseitigt Königin Azshara.", completion = "Wir sind nur Momente von der Drachenseele entfernt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30101] = { id = 30101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg zur Drachenseele", description = "Ich kann nicht einfach hochfliegen und die Drachenseele schnappen. Die Alten Götter beschützen sie.\n\nSchlimmer noch, der Schild der Götter ist von den wirbelnden arkanen Energien des Brunnens der Ewigkeit gestärkt und diese Energien werden von dem mächtigen Dämon Mannoroth fokussiert.\n\nLenkt Mannoroth ab und die Verbindung zwischen der Drachenseele und dem Brunnen wird unterbrochen. Ohne die Kraft des Brunnens ist der Schutz der Alten Götter geschwächt und die Drachenseele ungeschützt.\n\nUnd dann werde ich sie an mich nehmen.", sourceObjective = "Tötet Mannoroth.", progress = "Was?", completion = "Danke für Eure Hilfe.\n\nIhr kämpft gut. Ich hoffe, in der Zukunft noch einmal an Eurer Seite zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30102] = { id = 30102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stunde des Zwielichts", description = "Es ist nicht nötig, hier so lange herumzustehen. Habt Ihr vergessen? Wir KONTROLLIEREN DIE ZEIT. Erst recht, seitdem Ihr diesen Murozond in der Zukunft beseitigt habt.\n\nDie Drachenseele, die Ihr gerade befreit habt? Thrall hat sie schon, in Eurer Gegenwart. Und er wird Eure Hilfe benötigen.\n\nSeid Ihr bereit?", sourceObjective = "Sprecht mit Thrall in der Stunde des Zwielichts.", completion = "Ihr seid eingetroffen.\n\nGut, lasst uns anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30103] = { id = 30103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zum Wyrmruhtempel!", description = "Die Drachenseele... eine Waffe mit genug Macht, Todesschwinge zu besiegen. Dank Euch ist sie jetzt sicher in unserer Hand.\n\nKommt! Die Aspekte erwarten uns. Wir müssen die Drachenseele zum Wyrmruhtempel im Zentrum der Drachenöde bringen.", sourceObjective = "Eskortiert Thrall sicher zum Wyrmruhtempel.", completion = "Ich verdanke Euch mein Leben, Helden.\n\nJetzt, da sich die Drachenseele sicher in Wyrmruh befindet, verdanken vielleicht alle Bewohner Azeroths Euch ihr Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[30104] = { id = 30104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokumentation der Zeitwege", description = "Ihr… {name}, richtig? Ihr habt uns bereits in der Vergangenheit mit unserer Archivierung geholfen. Nun ja, genau genommen war es in der Zukunft, aber ich glaube, Ihr wisst, was ich meine. Zeit ist höchstgradig relativ.\n\nIch benötige mehr Informationen für unser Archiv. Da Ihr und Nozdormu nicht vorhabt, diesen Zeitstrang zu überschreiben, wie in der Endzeit, können wir noch mehr Informationen gewinnen.\n\nIch benötige Informationen über Hauptmann Varo'then, einen von Azsharas hübschen Handlangern und... hmm... oh, wie sieht es mit der Teufelswache unterhalb der Treppe aus?", sourceObjective = "Tötet einen Dämon der brennenden Legion, eine königliche Hofdame und Hauptmann Varo'then und gebt Alurmis Behältnis die Gelegenheit, ihre Informationen zu archivieren.", completion = "Nur selten haben wir die Gelegenheit, jemand so Mutiges wie Euch zu beschäftigen, {class}. Dank Eurer Bemühungen konnte unser Archiv weiter vervollständigt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30105] = { id = 30105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zwielichtprophet", description = "In dem Schreiben steht Folgendes:\n\n\"Die Stunde des Zwielichts ist gekommen. Der Weltenschamane Thrall nähert sich mit der Drachenseele Wyrmruh und droht noch ein letztes klägliches Mal, unseren glorreichen Meister zu vernichten.\"\n\n\"Haltet Thrall auf und wir werden unseren Krieg gewinnen. Ich werde Euch aus der Nähe beobachten.\"\n\n ~Der Zwielichtprophet", sourceObjective = "Findet und enttarnt den Zwielichtpropheten.", completion = "Es ist genauso, wie wir es vorhergesehen haben: Benedictus war der Zwielichtprophet. Nun weilt er nicht mehr unter uns.\n\nDer Schattenhammer hat heute einen herben Rückschlag hinnehmen müssen. Lasst uns hoffen, dass es sein Ende bedeutet.", sourceObjectiveStatus = "unverified-source-field" }
quests[30106] = { id = 30106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist vollbracht", description = "Prinz Furorion wird erfreut sein, von Eurem Erfolg zu erfahren. Begebt Euch zum Rabenholdtanwesen und erstattet ihm Bericht.\n\nDer Prinz ist bekannt dafür, seine Helfer äußerst großzügig zu entlohnen.", sourceObjective = "Meldet Prinz Furorion im Rabenholdtanwesen im Vorgebirge des Hügellands Euren Erfolg.", completion = "Das sind wunderbare Neuigkeiten, {name}. Altair war nicht der mächtigste der verbleibenden schwarzen Drachen, doch wie er die Gilneer manipuliert hat, war wahrlich bösartig.\n\nIch habe eine Belohnung für Euch vorbereitet. Diese Klingen mögen im Moment vielleicht nicht nach viel aussehen, doch in den richtigen Händen könnten sie zum Leben erwachen.\n\nVielleicht ja in EUREN Händen...", sourceObjectiveStatus = "unverified-source-field" }
quests[30107] = { id = 30107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelege im Gehege", description = "Die Dolche, die ich Euch gegeben habe, sind leblose Hüllen. Doch sie vermögen Großes zu vollbringen, wenn sie erst einmal in der Lage sind, die Art Macht zu speichern, an die ich denke.\n\nIhr müsst für mich Schattenedelsteine finden. Die Oberfläche dieser außergewöhnlichen Steine ist wie ein Fenster in die Unendlichkeit. Oftmals werden sie von Dienern des Schattenhammers benutzt, um die mächtigsten aller Elementare zu kontrollieren.\n\nAm Wyrmruhtempel tobt eine erbitterte Schlacht. Sammelt Elementiumedelsteine von Todesschwinges Dienern und bringt sie mir.", sourceObjective = "Sammelt 333 schattenhafte Edelsteine durch das Plündern von Elementiumedelsteinformationen von den Kreaturen in der Drachenseeleninstanz.", progress = "Wie viele Edelsteine habt Ihr gesammelt?\n\nSind die Diener meines Vaters genauso verderbt wie er?", completion = "Ah, seht Ihr, wie sie schimmern? Viele hochwertige Edelsteine glänzen im Licht, doch nur diese hier scheinen dunkel zu funkeln.\n\nIch werde sie verzaubern, während Ihr auf Eurer nächsten Mission seid.\n\nSeid Ihr bereit?", sourceObjectiveStatus = "unverified-source-field" }
quests[30108] = { id = 30108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Spitzel von Karazhan", description = "Euer nächstes Ziel ist der schwarze Drache Yntrige, der unter den Ruinen des Turms von Karazhan in eine Art arkane Entartung verwickelt ist.\n\nEure Hauptaufgabe ist es, Yntrige zu töten, aber wenn es Euch gelingt, mir eine Phiole ihres Blutes zu bringen, kann ich es nutzen, um die Dolche, die ich Euch gab, zu verstärken.\n\nZazzo, Euer Komplize, ist bereits auf dem Weg und wird Euch vor Ort erwarten. Er hat weitere Details für Euch.", sourceObjective = "Meldet Euch bei Zazzo Glitzerfinger in den Ruinen südöstlich von Karazhan.", completion = "Wahnsinn. Das ist verrückt!\n\nIch weiß nicht, was Yntrige dort unten vorhat, aber das gesamte Untergeschoss strahlt nur so vor boshafter arkaner Energie. Ein ganzer Kult verehrt sie als seine Göttin.\n\nWenn wir sie töten wollen, müssen wir das bald tun. Ich hoffe, Ihr seid hierfür bereit!", sourceObjectiveStatus = "unverified-source-field" }
quests[30109] = { id = 30109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut des Verräters", description = "Ich habe Yntrige im Keller des Meisters aufgespürt, ein weitläufiges Gemäuer, das sich in den Ruinen da vorn befindet.\n\nEs wimmelt von Drachenkultisten und Yntrige hat im gesamten Gebiet sonderbare Geräte zum Sammeln arkaner Energie aufgestellt. Vielleicht wisst Ihr sie zu Eurem Vorteil zu nutzen?\n\nGelangt unbemerkt an den Kultisten vorbei, tötet Yntrige und nehmt eine Phiole mit ihrem Blut für Furorion an Euch.\n\nIch behalte Euch im Auge und hol Euch da raus, wenn es Probleme gibt. Aber ich begleite Euch NICHT mit rein!", sourceObjective = "Schleicht Euch in den Keller des Meisters in den Ruinen um Karazhan, besiegt Yntrige und beschafft Euch eine Phiole mit schwarzem Drachenblut.", progress = "Yntrige. Tot?", completion = "Ihr wart erfolgreich? Sie ist tot? Unglaublich! Ihr habt ein Wunder vollbracht!\n\nZeigt mir das Blut. Ich kann seine Energien in einer arkanen Matrix für Euren Heimweg aufbewahren...", sourceObjectiveStatus = "unverified-source-field" }
quests[30110] = { id = 30110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Cataclysm - Raid Finder - 1st" }
quests[30111] = { id = 30111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Cataclysm - Raid Finder - Nth" }
quests[30112] = { id = 30112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Rechnung begleichen", description = "Utgardes Horden organisieren sich mit Hilfe der Ratschläge von Keleseth, dem San'layn-Botschafter der Geißel.\n\nWir können es nicht länger zulassen, dass die Vrykul von diesem Rat profitieren. Bringt ihn zum Schweigen.", sourceObjective = "Die Dunkle Waldläuferin Marrah möchte, dass Ihr Prinz Keleseth in Burg Utgarde tötet.", completion = "Rache ist süß. Und dies ist nur ein Vorgeschmack dessen, was Arthas noch bevorsteht.\n\nEr wird früh genug das bekommen, was er verdient hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[30113] = { id = 30113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg in den Tiefen", description = "<Zazzo verzaubert die Phiole voll Blut und gibt sie Euch dann so schnell zurück, als ob sie giftig wäre.>\n\nFertig! Die Phiole und Eure zwei Dolche sollten so schnell wie möglich zurück zu Furorion.\n\nIch weiß nicht, was er mit diesem Krams vorhat. So ganz unter uns, manchmal macht mir das kleine Drachenbalg Angst. Viel Glück!", sourceObjective = "Bringt die Phiole mit konserviertem Drachenblut und Eure Dolche Furcht und Rache zu Furorion im Rabenholdtanwesen im Vorgebirge des Hügellands.", progress = "Ah, Ihr seid zurückgekehrt! Ich kann Yntriges Gegenwart nicht mehr spüren. Ist sie tot? Oder ist sie irgendwie uns beiden entkommen?", completion = "Ihr seid wahrlich ein Meister Eures Faches. Yntrige ist tot und es ist Zeit, dass Ihr für Eure Bemühungen belohnt werdet.\n\n<Furorion nimmt die Phiole von Euch entgegen, sein Gesicht zeigt sowohl Verehrung als auch Verachtung. Er lässt die von Euch gesammelten Edelsteine einzeln in das Blut fallen und murmelt einen Zauberspruch.>\n\n<Ohne Vorwarnung gießt er das Blut über die Klingen der Dolche, deren Stahl sich wie lebendig zu winden und zu drehen scheint. Als sich der Rauch lichtet, haben die Dolche ihre Form verändert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[30116] = { id = 30116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wetzt Eure Klauen", description = "Wisst Ihr, warum ich Euch auftrage, die Drachen zu töten und das Leben der Sterblichen zu verschonen? Sie trifft keine Schuld. Sie müssen ihren eigenen Weg finden, ohne dass sich mein Volk einmischt.\n\nWir nähern uns dem Ende unserer Mission und es ist nun für Euch an der Zeit, Euren eigenen Weg zu wählen. Ich werde auch weiterhin Eure Waffen aufwerten, doch einzelne Schattenedelsteine werden dafür nicht mehr ausreichen. Ich benötige Elementiumedelsteinformationen. Ihr findet sie bei den Dienern meines Vaters...", sourceObjective = "Sammelt 60 Elementiumedelsteinformationen von den Kreaturen in der Drachenseeleninstanz.", progress = "Wie viele Formationen habt Ihr erhalten?\n\nDie Zähigkeit Eures Volkes ist mir weiterhin eine Inspiration!", completion = "Ihr habt es geschafft! Ich bin mir sicher, dass Ihr Euch und Eure Verbündeten in große Gefahr gebracht habt, um diese Edelsteine zu erhalten. Die von Euch erbrachten Opfer sollen belohnt werden. Ich werde die Edelsteine als Basis für eine mächtige Verzauberung benutzen.\n\nAber wir brauchen noch eine weitere Zutat. Seid Ihr bereit für Eure letzte und gefährlichste Mission, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[30117] = { id = 30117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinpflug ist durstig", description = "Entschuldigung... {name}? Habe ich Euren Namen richtig verstanden?\n\nIch komme aus Steinpflug im Westen. Man hat mich geschickt, um Notvorräte an Bier zu besorgen, aber die Brauerei Sturmbräu ist mit Brettern zugenagelt!\n\nEuer ansehnlicher Freund da - nein, nicht Trübtrunk, der andere - scheint ein paar Fässer zu haben. Könntet Ihr vielleicht ein Fässchen für eine Stadt in Not erübrigen?", sourceObjective = "Liefert ein Fässchen Kaiserbier an Lun Mai in Steinpflug im Tal der Vier Winde.", progress = "Grüße, {class}.", completion = "Endlich! Emmi ist zurück.\n\nIch hoffe, in der Brauerei Sturmbräu ist alles in Ordnung. Meine Männer machen ohne Bier nämlich nicht sonderlich viel her.", sourceObjectiveStatus = "unverified-source-field" }
quests[30118] = { id = 30118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vatermord", description = "Euer nächstes Ziel hat das Leben all meiner bisherigen Auftragsmörder gefordert. Ihr müsst meinen eigenen Vater für mich töten.\n\nIhr müsst Todesschwinge vernichten.\n\nDie Zeit wird knapp, denn sein Wahn hat bereits alle meiner Art verderbt und wenn er nicht aufgehalten wird, wird seine Dunkelheit die gesamte Welt verschlingen.\n\nWenn Ihr, auf wundersame Weise, erfolgreich seid und mir etwas von ihm bringt - einen Teil seiner Rüstung mit der er seine wahre chaosbringende Natur verhüllt hat - werde ich Euch eine Belohnung geben, die ihresgleichen sucht.", sourceObjective = "Vernichtet Todesschwinge und bergt ein Fragment von seinem Kiefer.", progress = "Was ist mit meinem Vater?", completion = "Ich kann es spüren, es ist wie ein dunkler Schatten, der sich vom Land hebt. Mein Vater ist tot!\n\n<Furorion nimmt das Kieferfragment entgegen. Seine Hände und sein Gesicht verschwimmen, während er eine dunkle Verzauberung murmelt und die Edelsteinformationen, die Ihr zuvor gesammelt habt, um seinen Kopf schwirren. Plötzlich zerbricht das Fragment des Kiefers, und mit einem furchtbaren Zischen erwachen Eure Zwillingsdolche.>\n\nEure Belohnung ist fertig. Schnell, nehmt sie. Ihr werdet sie gleich brauchen...", sourceObjectiveStatus = "unverified-source-field" }
quests[30119] = { id = 30119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Well of Eternity RP Tracker", description = "Meine Pflicht bindet mich, Euren Aussagen unverzüglich nachzugehen, {race}, was bedeutet, dass meine Mission hier nun in Eure Hände fällt.\n\nEin Anstieg uralter Magie, viel zu stark, um natürlichen Ursprungs zu sein, führte mich hierher. Seitdem habe ich eine zutiefst beunruhigende Entwicklung entdeckt.\n\nEin Ast wurde von Nordrassil abgebrochen und tief in die Feuerlande verschleppt. Dort droht ein mächtiges Ritual, Nordrassil zu verderben und ihn in Flammen aufzuzehren.\n\nIhr müsst einen Weg finden, das Ritual zu unterbrechen und den Zweig des Weltenbaumes zurückzuholen.", sourceObjective = "Erlangt den Zweig von Nordrassil aus den Feuerlanden zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[30120] = { id = 30120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Drak'Tharons", description = "Bald wird Drak'Tharon von den verdorb'nen Untoten gereinigt und wieder ihrer ursprünglichen noblen Aufgabe unterstellt werd'n. Als Belohnung für deine Hilfe werd'n dir die wertvollsten Schätze der Feste zur Verfügung steh'n, Mann!\n\nSobald du ihre Spitze erreicht hast, musst du mich beschwör'n, und ich führ' das Ritual durch.\n\nAber mich zu ruf'n, Mann, wird einiges kost'n. Du musst das Mojo von den Überlebenden sammeln.", sourceObjective = "Drakuru möchte, dass Ihr Drakurus Elixier an seinem Kohlenbecken innerhalb Drak'Tharons benutzt. Um das Elixier dort benutzen zu können, benötigt Ihr 5 Ausdauermojos.\n\nBereitgestellter Gegenstand:", completion = "Wir ham' großes geleistet, Mann! Un' das is' nur der Anfang…\n\nSuch mich in Zul'Drak auf, wenn die Zeit reif is'.\n\nEs gibt 'nen Krieg zu gewinnen, Mann!", sourceObjectiveStatus = "unverified-source-field" }
quests[30121] = { id = 30121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suchtrupp", description = "Ich habe einen Diplomaten entsandt, um in den Ruinen östlich von hier nach Verbündeten zu suchen.\n\nMein Diplomat ist noch nicht zurückgekehrt, und nun erzählt Kang mir auch noch, dass in diesem Dschungel ein übles Volk namens Mogu sein Unwesen treibt.\n\nChezin ist mein Freund und Lezas Bruder. Der Verlust eines Bruders würde sie zur Verzweiflung treiben. Sie macht sich wegen ihres Fiebers schon genug Sorgen.\n\nKönntet Ihr in den Ruinen östlich von hier Nachforschungen anstellen und in Erfahrung bringen, was geschehen ist?", sourceObjective = "Sucht in den Krasariruinen nach Chezin Morgenjäger.", completion = "G... Gift. Muss... Dezco... warnen...", sourceObjectiveStatus = "unverified-source-field" }
quests[30122] = { id = 30122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filigranes Silberfläschchen", description = "Ihr habt eine wunderschöne silberne Flasche mit filigraner Verzierung gefunden. Mit den richtigen Materialien und Euren Fähigkeiten in der Alchemie könntet Ihr etwas wirklich Magisches daraus machen.", sourceObjective = "Füllt die Phiole mit einer mächtigen alchemistischen Mixtur.", sourceObjectiveStatus = "unverified-source-field" }
quests[30123] = { id = 30123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huschereintopf", description = "Leza hat Fieber. Keine Mutter, die in Wehen liegt, sollte Fieber haben.\n\nMama Dornstab hat mir einst erzählt, dass Huschereintopf nahezu jede Krankheit heilen könne. Unterziehen wir dieses Wissen einer Prüfung.\n\nBesorgt mir ein paar unversehrte Huscherdrüsen, während ich die benötigten Kräuter sammle, dann werde ich einen Eintopf zubereiten.", sourceObjective = "Sammelt 5 unversehrte Huscherdrüsen.", progress = "Sogar in der Luft des Dschungels wimmelt es von Gefahren.", completion = "Ausgezeichnet! Für Kranke gibt es nichts Besseres als einen Huschereintopf.\n\nHier, nehmt das. Es ist ein kleines Erinnerungsstück von Mama Dornstab.", sourceObjectiveStatus = "unverified-source-field" }
quests[30124] = { id = 30124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blendet sie!", sourceObjective = "Tötet die Vorreiterin von Darnassus.", completion = "Gut gemacht, {name}. Ihr habt Euch vortrefflich geschlagen und uns etwas Zeit verschafft, unsere Verteidigung zu verstärken. Jetzt muss ich nur noch Dezco dazu bringen, in die Offensive zu gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30125] = { id = 30125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meisterlicher Profit", description = "Ein Wort: Tigerblut!\n\nDas wird sich besser verkaufen als damals Saronit auf dem Schwarzmarkt. Besonders, nachdem ich ein Gerücht über die tolle stärkende Wirkung und so verbreitet habe.\n\nDie Sache ist die, dass mir der Vorrat ausgegangen ist. Könnt Ihr ein paar mit Tigerblut gefüllte Phiolen für mich auftreiben? Ich werde Euch an der Gaunerei beteiligen.", sourceObjective = "Besorgt 12 mit Tigerblut gefüllte Phiolen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30126] = { id = 30126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kranich-Meisterschaft", description = "Die Sache bei der Jagd auf Vögel ist die, dass man Munition braucht - und ich habe keine. Die Sache bei der Jagd mit Nesingwary ist, dass man beweisen muss, dass man in Abschüssen und Prahlerei nicht nachlässt.\n\nKeine Jagd, keine Prahlerei. Und ich mag Prahlerei, also ist dies eine schlechte Situation.\n\nKann ich Euch anheuern, ein paar Karpfenjäger für mich zu töten? Ihr findet sie rauf und runter am Fluss westlich von hier.", sourceObjective = "Tötet 8 Karpfenjäger.", sourceObjectiveStatus = "unverified-source-field" }
quests[30127] = { id = 30127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung aus Dojan", description = "Mogu? Sie scheinen den Elfen zu ähneln - ein uraltes Volk mit einem überzogenen Anspruchsdenken. Alle in Azeroth müssen früher oder später lernen, dass die Horde diese Welt nicht \"besucht\". Wir sind hier, und wir bleiben hier.\n\nLehrt sie diese Lektion. Dünnt ihre Reihen in den Ruinen südlich und westlich von hier aus. Zerschmettert ihre wachsenden Streitkräfte, bevor sie sich für einen Angriff entscheiden.\n\nBringt in Erfahrung, wie diese Kreaturen kämpfen und wie sie sterben.", sourceObjective = "Tötet 6 Dojanieroberer, 8 Dojanispäher und 4 Dojanivollstrecker.", completion = "Das hier ist mehr als nur eine Bedrohung durch Banditen. Es handelt sich bei ihnen um ein altes Volk, das sich unter einem einzigen Banner sammelt. Lasst Euch das gesagt sein, diese Lande werden bald den Krieg kennenlernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30128] = { id = 30128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Teiche der Jugend", description = "Die Mogu haben die Teiche der Jugend gefunden!\n\nMama Dornstab hat mir alte Geschichten über sie erzählt. Zur Zeit des Mogukaiserreichs wurde das Wasser benutzt, um die Lebensdauer zu verlängern.\n\nAber aus irgendeinem Grund ging keine dieser Geschichten gut aus. Es scheint fast, als wäre das Wasser verflucht.\n\nWir sollten dieser Sache jedenfalls nachgehen. Es ist schließlich möglich, dass das Wasser Leza helfen könnte.\n\nAllem Anschein nach liegen die Teiche der Jugend an der Nordwestseite der Ruinen.", sourceObjective = "Besorgt Wasser aus den Teichen der Jugend.", progress = "Leza hat sehr große Schmerzen. Nur Mächte, die meine eigenen übersteigen, können sie und das Kind jetzt noch retten.", completion = "Ich bin so weit, dass ich alles versuchen würde. Dieses Land droht mir meine Frau und mein ungeborenes Kind wegzunehmen. Ich brauche alle Hilfe, die ich kriegen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[30129] = { id = 30129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Moguagenda", description = "Mogu versammeln sich nicht oft in so großer Zahl. Wir sollten in Erfahrung bringen, was sie planen.\n\nIch meine, gehört zu haben, wie jemand in der Nähe des Zentrums der Ruinen Befehle brüllt.\n\nWir sollten nachsehen, ob dieser Jemand nützliche Informationen hat.", sourceObjective = "Bergt die Dojani-Befehle.", progress = "Die Mogu haben einst als Kaiser geherrscht und alle Völker unterworfen, denen sie begegneten.\n\nEs scheint so, als versuchten diese Mogu, die Vergangenheit wieder aufleben zu lassen.", completion = "Wartet. In diesem Dokument ist von den Teichen der Jugend die Rede!\n\nGibt es sie wirklich?!", sourceObjectiveStatus = "unverified-source-field" }
quests[30130] = { id = 30130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilkräuter", sourceObjective = "Sucht 20 Kaiserliche Lotusblätter.", progress = "Ich wurde geschlagen, niedergestochen, von einer Klippe geworfen, von meinem eigenen Stab im Gesicht getroffen, von Stäben anderer im Gesicht getroffen... und ich bin mehr als einmal vom Aufzug in Donnerfels gefallen.\n\nKeiner dieser Schmerzen klingt auch nur halb so schlimm, wie das, was Leza durchmacht. Ich hoffe, dass dieser Tee hilft...", completion = "Ich danke Euch. Kor ist ein tapferer Krieger, doch manchmal fehlt es ihm an Mitgefühl. Das Leben sollte vor dem Tod stehen, sonst wird niemand von uns mehr da sein, wenn die Kämpfe vorüber sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[30131] = { id = 30131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leben", description = "Mein Kind kommt. Ich muss helfen, wie ich kann.\n\nBleibt in der Nähe, $GHeld:Heldin;. Wenn meine Frau und mein Kind überleben, möchte ich, dass sie das Gesicht <desjenigen erblicken, der/derjenigen erblicken> die; sie gerettet hat.", sourceObjective = "Sprecht mit Sonnenläufer Dezco und wartet auf die Geburt.", completion = "Sie... sie ist gestorben. Trotz all der Macht, die mir das Licht gegeben hat, konnte ich sie nicht retten.\n\nAber dank Eurer Hilfe... haben wir meine Söhne gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[30132] = { id = 30132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf in den Westen", sourceObjective = "Sucht die Späherin der Sonnenläufer in der Nähe des Kranichtempels.", progress = "Krieg. Es endet immer alles im Krieg.", completion = "{name}! Gerade rechtzeitig!\n\nWir haben in den Ruinen westlich von hier einen Hinterhalt für die Allianz gelegt, als wir selbst in einen Hinterhalt der Mogu gerieten. Sie verwenden Magierportale, um Verstärkung herbeizuschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30133] = { id = 30133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Wildnis", description = "Tief in der Wildnis am Südufer der Mündung des Krasarangs liegt der Tempel des Roten Kranichs, die Heimat des großen Chi-Ji und seiner gläubigsten Anhänger.\n\nSie sollten erfahren, was sich hier zugetragen hat.\n\nWenn Ihr in diese Richtung unterwegs seid, erweist mir bitte einen Gefallen: Wir schicken oft Vorräte zum Tempel, unser letzter Kurier ist jedoch nicht zurückgekehrt. Haltet bitte auf Eurem Weg nach Zeichen von ihm Ausschau. Er müsste bei der Weggabelung am Dojani nach Norden abgebogen sein. Sucht Koro Nebelgänger auf, wenn Ihr den Tempel erreicht.", sourceObjective = "Findet den vermissten Kurier aus Zhus Wacht am nördlichen Flusslauf des Dojani, begebt Euch dann zum Tempel des Roten Kranichs und sprecht mit Koro Nebelgänger.", completion = "Verstehe... Und das Sha hat bereits die gesamte Provinz durchtränkt, oder?\n\nNun, es tut mir leid, aber ich muss Euch sagen, dass auch der Tempel vom Sha überschwemmt ist. Diejenigen unter uns, die nicht getötet oder... besessen wurden, oder was auch immer, rennen um ihr Leben.\n\nWenn Ihr das Sha bei Zhus Wacht besiegt habt, muss ich Euch inständig anflehen, uns zu helfen, hier mit dem Sha fertigzuwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30134] = { id = 30134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildes in der Wildnis", description = "Willkommen beim Orden der Wolkenschlange, {race}. Ich kann an dem Funkeln in Euren Augen erkennen, dass Ihr dem Orden beitreten möchtet.\n\nLasst mich Euch ansehen.\n\n<Die Älteste Anli hält sanft Euren Kopf und blickt Euch tief in die Augen.>\n\nHmm. Ich erkenne Ehrlichkeit und Aufrichtigkeit in Eurem Herzen. Ihr habt eine lange Reise hinter Euch, aber leider seid Ihr noch nicht am Ziel angekommen.\n\nEuer Weg in den Orden beginnt hier und jetzt.\n\nSprecht mit Ausbilder Tong auf der Windwärtsinsel im Nordosten, um den ersten Schritt zu tun.", sourceObjective = "Findet Ausbilder Tong auf der Windwärtsinsel im Jadewald.", completion = "Gott seid Dank haben sie endlich jemanden geschickt!\n\nHier sind die Dinge außer Kontrolle geraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[30135] = { id = 30135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entgegen aller Wahrscheinlichkeit", description = "Zunächst hatten die Schlängelschuppen zu viel Angst, sich den wilden Schlangen zu nähern.\n\nDann habe ich sie dabei erwischt, wie sie im Schutz der Nacht Eier gestohlen haben.\n\nJetzt töten sie sowohl ausgewachsene als auch frisch geschlüpfte Schlangen!\n\nWenn wir nichts unternehmen, werden diese sanften Kreaturen vollkommen ausgerottet werden. Dann gäbe es überhaupt keinen Orden der Wolkenschlange mehr, dem Ihr beitreten könntet!\n\nTötet diese gemeinen Schlängelschuppen, dann sehen wir weiter.", sourceObjective = "Tötet 8 Reißer der Schlängelschuppen oder Eitrinker der Schlängelschuppen.", completion = "Ich danke Euch, {race}.\n\nIch habe versucht, die Schlängelschuppen so weit wie möglich zurückzudrängen, aber sie waren mir zahlenmäßig überlegen.\n\nEure Arbeit heute wird helfen, eine gesamte Generation von Wolkenschlangen zu retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[30136] = { id = 30136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leere Nester", description = "Als die Angriffe begannen, sind die Jungtiere in Panik geflohen.\n\nSie irren überall allein und verängstigt auf der Insel umher.\n\nWenn Ihr helfen möchtet, dann nehmt dieses Seil und fangt damit die Jungtiere ein. Bringt sie zurück in ihre Nester. Bringt sie zurück nach Hause.", sourceObjective = "Fangt 6 Windwärtsjungtiere mit dem Seil ein und bringt sie zurück in ihre Nester.", completion = "Keine Sorge, in ihren Nestern sind die Jungtiere sicher.\n\nIch kann Euch gar nicht genug dafür danken, dass Ihr gerade rechtzeitig gekommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[30137] = { id = 30137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eier sammeln", description = "Ahh, ich hätte es wissen sollen! Ihr seht aus wie <ein ehrgeiziger Initiand/eine ehrgeizige Initiandin>.\n\nIch würde Euch von Herzen gern bei der Wahl eines Schlangeneis unterstützen, aber die Schlängelschuppen haben sämtliche Wolkenschlangennester geplündert.\n\nEs tut mir furchtbar leid. Ich weiß nicht, was ich sagen soll.\n\nWenn Ihr nicht verrückt genug seid, Euch in ein Sauroklager im Osten zu schleichen und einige der gestohlenen Wolkenschlangeneier zurückzuholen, dann kann ich Euch leider nicht helfen.", sourceObjective = "Sammelt 6 Schlangeneier ein.", progress = "Die Saurok lagern die gestohlenen Eier in ihrem Lager.", completion = "Oh, wundervoll!\n\nDiese Eier sehen... also... etwas zu klein aus. Konntet Ihr denn keine besseren finden?\n\nAber was soll's... so, wie die Dinge stehen, können wir nicht wählerisch sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[30138] = { id = 30138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auserwählte", description = "Ich habe alle Eier untersucht, {name}. Und von denen, die Ihr mir gebracht habt, habe ich die drei vielversprechendsten ausgesucht.\n\nIhr müsst Euch aber für ein Ei entscheiden, das Ihr mitnehmen wollt. Seid Ihr bereit, Eure endgültige Entscheidung zu treffen?", sourceObjective = "Sprecht mit Ausbilder Tong auf der Windwärtsinsel im Jadewald.", completion = "Ihr müsst Euch aber für ein Ei entscheiden, das Ihr mitnehmen wollt.\n\nTrefft Eure Wahl mit Umsicht, denn Ihr könnt sie nicht rückgängig machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30139] = { id = 30139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Reiters Reise", description = "Ausgezeichnet, einfach ausgezeichnet! Ich werde die anderen Eier unbehelligt zu ihren Nestern zurückbringen.\n\nIn der Zwischenzeit könnt Ihr Euer Ei bei Ausbilder Himmelsdorn im Arboretum abliefern.", sourceObjective = "Kehrt zu Ausbilder Himmelsdorn im Arboretum im Jadewald zurück.", progress = "Die wilden Wolkenschlangen leben in einem anfälligen Gleichgewicht mit der Natur. Ihre seltenen Eier sind Feinden fast schutzlos ausgeliefert.", completion = "Ah, ja - die Älteste Anli hat erwähnt, dass ein neuer Schüler seinen Weg zu uns gefunden hat. Und wie ich sehe, habt Ihr bereits ein Wolkenschlangenei gewählt.\n\nIch werde Euch in seiner Pflege unterweisen. Lasst es mich für einen Moment ansehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30140] = { id = 30140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Reiters Reise", description = "Ausgezeichnet, einfach ausgezeichnet! Ich werde die anderen Eier unbehelligt zu ihren Nestern zurückbringen.\n\nIn der Zwischenzeit könnt Ihr Euer Ei bei Ausbilder Himmelsdorn im Arboretum abliefern.", sourceObjective = "Kehrt zu Ausbilder Himmelsdorn im Arboretum im Jadewald zurück.", progress = "Die wilden Wolkenschlangen leben in einem anfälligen Gleichgewicht mit der Natur. Ihre seltenen Eier sind Feinden fast schutzlos ausgeliefert.", completion = "Ah, ja - die Älteste Anli hat erwähnt, dass ein neuer Schüler seinen Weg zu uns gefunden hat. Und wie ich sehe, habt Ihr bereits ein Wolkenschlangenei gewählt.\n\nIch werde Euch in seiner Pflege unterweisen. Lasst es mich für einen Moment ansehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30141] = { id = 30141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Reiters Reise", description = "Ausgezeichnet, einfach ausgezeichnet! Ich werde die anderen Eier unbehelligt zu ihren Nestern zurückbringen.\n\nIn der Zwischenzeit könnt Ihr Euer Ei bei Ausbilder Himmelsdorn im Arboretum abliefern.", sourceObjective = "Kehrt zu Ausbilder Himmelsdorn im Arboretum im Jadewald zurück.", progress = "Die wilden Wolkenschlangen leben in einem anfälligen Gleichgewicht mit der Natur. Ihre seltenen Eier sind Feinden fast schutzlos ausgeliefert.", completion = "Ah, ja - die Älteste Anli hat erwähnt, dass ein neuer Schüler seinen Weg zu uns gefunden hat. Und wie ich sehe, habt Ihr bereits ein Wolkenschlangenei gewählt.\n\nIch werde Euch in seiner Pflege unterweisen. Lasst es mich für einen Moment ansehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30142] = { id = 30142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist ein...", description = "Oh! Jeden Moment kann ein Junges aus diesem Ei schlüpfen!\n\nDer kleine Kerl scheint Euch möglichst schnell kennenlernen zu wollen.\n\nAlso, seid Ihr bereit?", sourceObjective = "Beobachtet das Ausschlüpfen Eures Eis.", progress = "Ein stolzer Moment in Eurem Leben!", completion = "Glückwunsch! Hier ist Euer ganz eigenes, wunderschönes Jungtier.\n\nBitte kümmert Euch gut darum, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30143] = { id = 30143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie vermehren sich wie Unkraut", description = "Ah, Ihr seid es wieder, {name}.\n\nAusbilderin Windklinge sucht schon nach Euch. Ihr findet sie auf dem Hügelkamm im Osten.\n\nSie hat ein paar Neuigkeiten über Eure Wolkenschlange für Euch.", sourceObjective = "Sprecht mit Ausbilderin Windklinge im Arboretum.", progress = "Ihr macht Euch wirklich gut.", completion = "Glückwunsch, {name}.\n\nDie Früchte der eigenen Arbeit zu ernten, ist eine Genugtuung.", sourceObjectiveStatus = "unverified-source-field" }
quests[30144] = { id = 30144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugausbildung: Ringelreihen", description = "Jetzt, da Eure Schlange ausgewachsen ist, seid Ihr bereit, mit der Flugausbildung zu beginnen.\n\nWie alle Neulinge müsst Ihr ganz von vorn beginnen.\n\nEure erste Aufgabe ist sehr einfach. Fliegt durch 6 der Wolkenringe zwischen den Spitzen im Osten.", sourceObjective = "Reitet Eure Wolkenschlange durch 6 Wolkenringe.", progress = "Wie war Euer erster Flug?", completion = "Was habt Ihr in dieser Lektion gelernt?\n\nGeschwindigkeit. Es hängt alles von Geschwindigkeit ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[30145] = { id = 30145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugausbildung: Volle Kraft voraus", description = "Die nächste Aufgabe wird etwas schwerer.\n\nSeid Ihr bereit?", sourceObjective = "Folgt Ausbilderin Windklinge.", completion = "Ihr habt Euch besser geschlagen als erwartet. Nicht schlecht für einen neuen Schüler.", sourceObjectiveStatus = "unverified-source-field" }
quests[30146] = { id = 30146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieblingsgericht", description = "Wolkenschlangen lieben es zu essen und eines ihrer Lieblingsgerichte ist Zuckerelritze.\n\nDiese Fische kann man überall in Pandaria sowohl in Süß- als auch in Salzwassergewässern finden. Ich gehe davon aus, dass Ihr kein unbegabter Angler seid und Eure eigene Angelrute habt, um sie zu fangen?\n\nBringt mir ein paar dieser Fische und ich bin sicher, dass diese hungrigen Biester hier Euch sehr dankbar sein werden.", sourceObjective = "Angelt 10 Zuckerelritzen aus Süß- oder Salzwassergewässern in Pandaria.", progress = "Habt Ihr einen guten Ort zum Fischen gefunden?", completion = "Das ist ja wundervoll! Diese Fische werden auf jeden Fall ausreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30147] = { id = 30147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragmente der Vergangenheit", description = "Das Erbe des Ordens der Wolkenschlange reicht Jahrtausende zurück. Und obwohl wir versucht haben, diese uralte Kultur zu bewahren, sind einige alte Techniken im Laufe der Zeit verloren gegangen.\n\nIhr könntet uns helfen, einen Teil dieses Wissen zurückzuerlangen, indem Ihr in Pandarias Grabungsstätten nach Hinweisen auf unsere Vergangenheit sucht.\n\nNutzt Eure Archäologiefertigkeiten, während Ihr Pandaria durchsucht, und bringt mir zurück, was immer Ihr finden könnt.", sourceObjective = "Sucht archäologische Grabungsorte in ganz Pandaria auf und nutzt Eure Archäologenfertigkeiten, um 6 Schlangenreiterrelikte zu finden.", progress = "Wie liefen denn die Ausgrabungen?", completion = "Das ist wirklich erstaunlich, {name}. Diese Relikte sind für unsere Studien von unermesslichem Wert. Von diesen Fragmenten werden wir viel lernen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[30148] = { id = 30148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur eine Fleischwunde", description = "Viele der Jungtiere auf der Windwärtsinsel sind im Zuge der Kämpfe verletzt worden.\n\nIch habe gehört, dass Ihr uns helfen könnt, weil Ihr Zugriff auf mächtige Verbände habt.\n\nBitte begebt Euch in den Nordosten und verwendet einige Eurer besten Verbände, um die verletzten Jungen zu retten.", sourceObjective = "Verwendet Windwollverbände oder schwere Windwollverbände, um 8 verletzte Junge auf der Windwärtsinsel zu versorgen. Sie können von Schneidern angefertigt oder im Auktionshaus gekauft werden.", completion = "Wundervoll! Nur gut, dass Ihr Zugriff auf solch mächtige Gegenstände habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[30149] = { id = 30149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fest für die Sinne", description = "Ich habe gehört, dass Ihr etwas vom Kochen versteht.\n\nDas trifft sich gut, denn die Schlangen lieben Fischküchlein.\n\nWenn Ihr Eure Kochfertigkeiten einsetzt und mir 5 dieser Gerichte bringen könnt, würdet Ihr die Wolkenschlangen hier sehr glücklich machen.", sourceObjective = "Sammelt 5 Fischküchlein.", progress = "Konntet Ihr die benötigten Zutaten finden?", completion = "Oh, die sehen ja wirklich sehr lecker aus. Ihr versteht wirklich etwas vom Kochen!", sourceObjectiveStatus = "unverified-source-field" }
quests[30150] = { id = 30150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süß wie Honig", description = "<Das Jungtier huscht hin und her, bevor es zu winseln und wimmern beginnt.>\n\nDas Verhalten der Wolkenschlange lässt Euch erahnen, dass es allerhöchste Zeit für ein süßes Leckerli ist.\n\nDie wohlriechenden Bäume des Arboretums beherbergen viele Bienenstöcke.\n\nEs sollte relativ einfach sein, ein paar Waben von den Honigbewahrern in der Nähe zu sammeln.", sourceObjective = "Sammelt 30 Honigwaben von wütenden Honigbewahrern im Arboretum ein.", progress = "<Das Jungtier überschlägt sich vor Freude über Eure Rückkehr.>", completion = "Das Jungtier springt auf Eure Hand. Es wickelt seinen langen, gewundenen Schwanz um Euch und beginnt, den Honig von Euren Fingern zu lecken.\n\nDas kitzelt!", sourceObjectiveStatus = "unverified-source-field" }
quests[30151] = { id = 30151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fang!", description = "<Das Jungtier blickt Euch lustlos und gelangweilt an.>\n\nIhr bekommt das Gefühl, dass die Schlange genug davon hat, den ganzen Tag lang eingesperrt zu sein.\n\nKann man Wolkenschlangen eigentlich auch Stöckchen holen lassen?", sourceObjective = "Benutzt den Flummi. Dann fangt ihn und werft ihn achtmal zu Eurem Jungtier zurück.", completion = "Sieh einer an - Ihr und Eure Schlange scheint ja richtig Spaß zu haben! Gut gemacht, {name}. Indem Ihr mit ihr spielt, stärkt Ihr sowohl ihre geistigen als auch ihre körperlichen Fähigkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[30152] = { id = 30152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Himmelsrennen", description = "Die Zeit des großen Rennens ist gekommen!\n\nFolgt dem Kurs entlang der Spitzen und sammelt 10 Flaggen von den Ballon-Kontrollpunkten ein.\n\nUnd wenn Ihr damit fertig seid, müsst Ihr das Rennen unterhalb der Ziellinie beenden.\n\nDas wird ein hartes Rennen und ich wünsche Euch Glück. Sprecht mich einfach an, wenn Ihr bereit seid.", sourceObjective = "Beendet das Himmelsrennen, indem Ihr durch 10 Kontrollpunkte hindurchfliegt und dann die Ziellinie am Arboretum unterquert.", completion = "Hervorragend! Wie fühlt es sich an, das Himmelsrennen beendet zu haben?\n\nIhr müsst ganz erpicht darauf sein, Euren Preis zu erhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[30153] = { id = 30153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volle Kraft voraus", description = "Zeit für eine weitere Ausbildungslektion.\n\nFolgt mir auf dem Kurs um die Spitzen. Mal sehen, ob Ihr an mir dranbleiben könnt, ohne herunterzufallen.", sourceObjective = "Folgt Ausbilderin Windklinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[30154] = { id = 30154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schnellste Weg zum Herzen einer Schlange", description = "<Das Jungtier blickt Euch mürrisch an.>\n\nOh oh... Sieht aus, als wenn jemand heute schlecht drauf ist!\n\nZum Glück wisst Ihr genau, was den kleinen Racker wieder aufmuntern wird.\n\nWolkenschlangen lieben den Geschmack von Tigerfleisch, aber die Beschaffung ihrer zarten Flanken kann sich mitunter... schwierig... gestalten.\n\nZum Glück wisst Ihr auch, dass sich auf der Windwärtsinsel im Nordosten ein paar dicke, saftige Tiger finden lassen.\n\nSicher, Ihr könntet Euch ein paar Kratzer (oder Schlimmeres) einfangen, aber für den kleinen Rabauken macht man es doch gerne... oder?!", sourceObjective = "Sammelt 5 Tigerflanken.", progress = "Sieht aus, als wäre die Aufgabe erledigt.", completion = "Wie ich sehe, habt Ihr hart gearbeitet und Futter für Eure hungrige kleine Schlange beschafft. Gut gemacht. Es scheint im Moment noch nicht sonderlich lohnenswert zu sein, doch Eure Schlange wird Eure Anstrengungen nicht vergessen und Euch dafür in ihr Herz schließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30155] = { id = 30155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gleichgewicht wiederherstellen", description = "Die Lage auf den Inseln ist immer noch düster, {name}.\n\nDie Schlängelschuppen haben nicht auf unsere Friedensgesuche reagiert, also bleibt uns nur noch eine Möglichkeit.\n\nUm die wilden Wolkenschlangen zu schützen, müssen wir die Insel von ihnen befreien. Nur dann können die Wolkenschlangen wieder in Frieden leben.", sourceObjective = "Tötet 8 Reißer der Schlängelschuppen oder Eitrinker der Schlängelschuppen.", progress = "Die Wilderer werden die Wolkenschlangen vollständig ausrotten, wenn wir sie nicht aufhalten.", completion = "Wenn die Wilderer der Diplomatie keine Beachtung schenken, müssen sie eben unsere Klingen zu spüren bekommen. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30156] = { id = 30156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fütterungszeit", description = "<Die Schlange schnellt vorwärts und beißt Euch in den Finger.>\n\nAutsch! Wie es aussieht, ist das kleine Biest zweifelsohne sehr hungrig. Ihr erinnert Euch an ein paar fleischig aussehende Schildkröten, die sich auf der Insel im Nordosten finden lassen, wo die wilden Wolkenschlangen leben.\n\nVielleicht kann ja ein bisschen Schildkrötenfleisch den Heißhunger Eures Jungtiers stillen.", sourceObjective = "Sammelt 3 Stücke Salzrückenfleisch und verfüttert sie an Euer Jungtier.", completion = "Ihr lernt schnell, junger Trainer. Salzrückenfleisch ist zäh, aber reich an Nährstoffen, die ein Jungtier zum Wachsen benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30157] = { id = 30157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch leerere Nester", description = "Dem Himmel sei Dank, noch ein Wolkenschlangentrainer!\n\nIch habe gerade erfahren, dass die wild lebenden Jungtiere der Windwärtsinsel im Nordosten in schlimme Schwierigkeiten geraten sind!\n\nWer kümmert sich denn um die süßen kleinen Babys, während die ausgewachsenen Schlangen die schrecklichen Saurok bekämpfen? Niemand!\n\nWIR MÜSSEN SIE RETTEN!\n\nIch schicke jeden Trainer, den ich finden kann, dorthin, um zu helfen. Wenn Ihr nicht zu beschäftigt seid, könnt Ihr dann bitte auch dafür sorgen, dass alle Jungtiere wieder sicher in den Nestern ihrer Mütter landen?", sourceObjective = "Fangt 6 Windwärtsjungtiere mit dem Seil ein und bringt sie zurück in ihre Nester.", completion = "Wie ich sehe, habt Ihr Euch dort draußen sehr gut um die Jungtiere gekümmert. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[30158] = { id = 30158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entwaffnung des Feindes", description = "Wenn wir die Wilderer aufhalten wollen, müssen wir entschlossener vorgehen.\n\nWenn wir den Feinden die Hauptwaffen für das Töten und Fangen von Schlangen abnehmen können, bereiten wir vielleicht ihrem ganzen Vorhaben ein Ende.\n\nIch möchte, dass Ihr in ihr Gebiet im Osten der Windwärtsinsel eindringt und ihnen die Waffen stehlt.\n\nEine Katze ohne Krallen kann niemanden kratzen.", sourceObjective = "Sammelt 5 Harpunen der Schlängelschuppen ein.", progress = "Habt Ihr die Sache erledigt?", completion = "Wir haben sie geschwächt, aber wir dürfen uns nicht zu früh freuen. Auch ein zahnloser Tiger ist noch gefährlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[30159] = { id = 30159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artenschutz", description = "Oh nein! Wir müssen sie aufhalten! Ihr seid {name}, oder? Der Orden benötigt Eure Hilfe!\n\nWisst Ihr, was diese fürchterlichen Saurok der Schlängelschuppen tun?\n\nSie sind dreist genug, Wolkenschlangeneier direkt aus den Nestern der Matriarchinnen zu stehlen!\n\nWährend die Wolkenschlangen immer seltener werden, nehmen diese Bestien die Eier und... und...\n\n<Suchi atmet tief durch.>\n\n... und verspeisen sie als ihr Abendessen! Es ist schrecklich!\n\nMacht Euch auf zur Windwärtsinsel im Nordosten und bringt alle unbeschädigten Eier, die ihr finden könnt, in Sicherheit. Als Schüler des Ordens ist es unsere Pflicht!", sourceObjective = "Sammelt 8 gestohlene Eier.", progress = "Werden diese gemeinen Schlängelschuppensaurok denn niemals aufgeben?", completion = "Gut gemacht, {name}. Als Suchi mir erzählte, dass sie Euch nach den gestohlenen Eiern ausgeschickt hatte, wusste ich, dass Ihr die Aufgabe erledigen würdet.\n\nUnsere Ausbilder werden sicherstellen, dass diese Eier an einen sicheren Ort zurückgebracht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30160] = { id = 30160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Rubinsplitter für Ella", progress = "Hallo {name}, schön, Euch wiederzusehen.", completion = "Oh, ist der für mich? Ich, ich weiß gar nicht, was ich sagen soll.\n\nDer ist wunderschön, vielen Dank!" }
quests[30163] = { id = 30163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für den Stamm", description = "Wir haben uns in die Zuflucht zurückgezogen, als die Mogu angriffen, haben aber unterwegs eine Menge Leute verloren.\n\nReist von hier aus nach Westen und Norden und sucht nach Gefangenen. Befreit so viele wie möglich, damit sie uns im Kampf verstärken.\n\nSolltet Ihr welche von der Allianz treffen, so überlasst sie ihrem Schicksal.", sourceObjective = "Rettet 8 Gefangene der Morgenjäger.", completion = "Wir haben bereits so viele verloren. Ich weigere mich, noch mehr zu verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[30164] = { id = 30164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Steinpflug-Konvoi", description = "Ich habe versucht, so viele der Steinpfluggesandten wie nur irgend möglich zu retten, aber diese \"Mantis\" haben viele von ihnen in den Dschungel gezerrt.\n\nDiese Zivilisten brauchen unsere Hilfe.\n\nBitte nehmt die Kräuter, die Ihr vorher gesammelt habt. Ich habe sie mit den letzten Gaben des Lichts erfüllt, die mir noch zur Verfügung stehen. Behandelt so viele Steinpfluggesandte damit, wie Ihr könnt.", sourceObjective = "Wendet den kaiserlichen Lotusumschlag bei 7 Gesandten von Steinpflug an.", progress = "Die erste Pflicht eines Sonnenläufers besteht darin, Leben zu bewahren und zu schützen.", completion = "Dank Euch trudeln die Zivilisten wieder hier ein. Diese \"Mantis\"-Kreaturen stellen eine ernste Bedrohung dar. Wir werden bald unsere Streitkräfte sammeln müssen, um die Lage zu entschärfen.\n\nEiner der Gesandten bat mich, Euch das hier als Zeichen seines Dankes zu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[30165] = { id = 30165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Blaue Schlange gewählt" }
quests[30166] = { id = 30166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Grüne Schlange gewählt" }
quests[30167] = { id = 30167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Picked Gold Serpent" }
quests[30168] = { id = 30168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diebische Räuber", description = "Saurok!\n\nDiese bösartigen Kreaturen sind vom Töten und Stehlen besessen. Sie haben unsere Siedlung ohne Vorwarnung und völlig unprovoziert angegriffen.\n\nBitte, {class}, könnt Ihr uns helfen?\n\nHelft uns, unsere letzten Besitztümer vor diesen Flussklingenräubern zu retten, die sich entlang des Flusses aufhalten, und wir werden Euch gerne belohnen.", sourceObjective = "Beschafft 5 Teile der geplünderten Jinyubeute wieder.", progress = "Ich glaube, sie haben sogar meinen heiligen Spucknapf gestohlen.", completion = "Nicht viele würden anhalten, um einem Dorf in Not zu helfen... besonders so tief in der Wildnis.\n\nIhr seid wahrlich ein Champion, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30169] = { id = 30169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuberanführer Slovan", description = "Die Räuber werden von einem besonders gewalttätigen Saurok namens Slovan angeführt. Der Kranichtempel kommt uns normalerweise zu Hilfe, wenn Slovan angreift, aber mittlerweile sind wir unterlegen und werden ausmanövriert.\n\nBitte, {class}, helft uns, indem Ihr diesen Räuberanführer ausschaltet.\n\nIhr findet ihn in seinem Versteck hinter den Krasarifällen.", sourceObjective = "Tötet Slovan.", progress = "Slovan war immer schon eine Plage, aber ohne die Verteidigung durch den Kranichtempel wurde er zu einer echten Bedrohung.", completion = "Ihr habt uns heute einen großen Dienst erwiesen. Ich danke Euch im Namen meiner Leute.\n\nBitte nehmt dies als Zeichen unserer Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[30172] = { id = 30172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fassgeleit", description = "Nö, nö, zerbrecht Euch mal nicht den Kopf, ich kann die Fässer schon selbst schleppen.\n\nIch bin vielleicht nicht der schönste oder klügste oder unterhaltsamste Pandaren, aber dafür stärker als ein Mushan.\n\nAber den Weg könnt Ihr mir gern zeigen.", sourceObjective = "Führt Trübtrunk zurück nach Halbhügel.\n\nWenn Ihr Trübtrunk verliert, könnt Ihr ihn neben der riesigen Banane am Goldfächer wiederfinden.", progress = "Wo ist Trübtrunk?", completion = "Sehr gut! Das Wasser ist da!", sourceObjectiveStatus = "unverified-source-field" }
quests[30173] = { id = 30173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Pigs!" }
quests[30174] = { id = 30174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Familie", description = "Kor sollte uns mittlerweile eingeholt haben. Er meinte, er würde aufbrechen, um die Ruinen von Korja östlich von hier zu sichern. Er wollte sich mit uns treffen, um uns bei der Bedrohung durch die Mantis zu helfen.\n\nVielleicht braucht er Hilfe gegen Bodenbrecher Brojai. Könntet Ihr ihn unterstützen? Kang und ich werden Euch in Kürze folgen.", sourceObjective = "Sucht Kor Bluthauer.", progress = "Dieses Land fordert so viel.", completion = "Danke, dass Ihr meinen Freund gerächt habt, {name}.\n\nIch weiß, er hätte gewollt, dass Ihr einen seiner Gegenstände als Andenken und als Zeichen seiner Dankbarkeit bei Euch tragt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30175] = { id = 30175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mantis", description = "Die Mantis! Sie kamen aus dem Nichts, schlugen unseren Konvoi in Trümmer und versprengten unsere Leute in alle Richtungen.\n\nJetzt bereiten sie einen Angriff auf Steinpflug vor.\n\nBitte, {class}, vernichtet ein paar dieser Bestien, bevor sie zahlreich genug sind, um uns zu umzingeln.\n\nWenn mein Cousin, Botschafter Len, immer noch am Leben ist und sich in unserem Konvoi befindet, sollte er Euch für Eure Hilfe belohnen können.", sourceObjective = "Tötet 10 Vorläufer der Ik'thik.", completion = "Danke für Eure Hilfe, {class}! Ich habe noch nie gesehen, wie sich jemand so den Mantis entgegengeworfen hat.\n\nNun, außer den Shado-Pan natürlich...", sourceObjectiveStatus = "unverified-source-field" }
quests[30177] = { id = 30177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täglicher zufälliger, heroischer Dungeon (Erster) (Cataclysm)" }
quests[30178] = { id = 30178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Wildnis", description = "Tief in der Wildnis am Südufer der Mündung des Krasarangs liegt der Tempel des Roten Kranichs, die Heimat des großen Chi-Ji und seiner gläubigsten Anhänger.\n\nSie sollten erfahren, was sich hier zugetragen hat.\n\nWenn Ihr in diese Richtung unterwegs seid, erweist mir bitte einen Gefallen: Wir schicken oft Vorräte zum Tempel, unser letzter Kurier ist jedoch nicht zurückgekehrt. Haltet bitte auf Eurem Weg nach Zeichen von ihm Ausschau. Er müsste bei der Weggabelung am Dojani nach Süden abgebogen sein. Sucht Koro Nebelgänger auf, wenn Ihr den Tempel erreicht.", sourceObjective = "Findet den vermissten Kurier aus Zhus Wacht am südlichen Flusslauf des Dojani, begebt Euch dann zum Tempel des Roten Kranichs und sprecht mit Koro Nebelgänger.", completion = "Verstehe... Und das Sha hat bereits die gesamte Provinz durchtränkt, oder?\n\nNun, es tut mir leid, aber ich muss Euch sagen, dass auch der Tempel vom Sha überschwemmt ist. Diejenigen unter uns, die nicht getötet oder... besessen wurden, oder was auch immer, rennen um ihr Leben.\n\nWenn Ihr das Sha bei Zhus Wacht besiegt habt, muss ich Euch inständig anflehen, uns zu helfen, hier mit dem Sha fertigzuwerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30179] = { id = 30179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergiftet!", description = "Die... Mogu. Traut ihnen nicht. Gift. Holt Proben... Holt Klingen. Bringt sie zu Dezco... in Donnerkluft, westlich von hier.", sourceObjective = "Sammelt 5 vergiftete Klingen der Mogu.", progress = "Habt Ihr Neuigkeiten von Chezin?", completion = "Chezin ist tot? Das sind wirklich sehr schlechte Neuigkeiten. Kor, Chezin und ich haben an fast jeder Küste, die einen Namen trägt, gegen Drachen, Untote und die Allianz gekämpft.\n\nIhn auf diese Weise zu verlieren...\n\nDanke, dass Ihr diese Waffen beschafft habt. Durch sie sollten wir viel über unseren neuen Feind erfahren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[30180] = { id = 30180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Ach und Weh", description = "Bei meiner Frau Leza werden bald die Wehen einsetzen, aber sie ist sehr, sehr krank. Ich muss sie warm halten, aber unser Vorrat an trockenem Feuerholz ist aufgebraucht.\n\nKönntet Ihr ein paar Äste und Zweige von den Bäumen in der Nähe für mich holen? Die Zeit drängt!", sourceObjective = "Sammelt 8 Stücke Feuerholz.", sourceObjectiveStatus = "unverified-source-field" }
quests[30181] = { id = 30181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mushanjagd", description = "Mushan! Schaut Euch mal an, wie groß die sind. Und wahrscheinlich so alt wie der Staub, auf dem sie umhertrotten. Eine schöne Trophäe.\n\nWenn Ihr Euch also als <Großwildjäger/Großwildjägerin> beweisen wollt, solltet Ihr mit ihnen anfangen.", sourceObjective = "Tötet 15 Staubrückenmushan.", completion = "Gut gemacht, {name}.\n\nMein Vater reist über das Meer zu einem neuen Kontinent, nur um öde Wölfe zu jagen.\n\nIch jage ja lieber Kreaturen mit ordentlich Fleisch auf den Knochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30182] = { id = 30182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fuchsjagd", description = "Auf meiner Pirsch östlich von hier habe ich ein paar Füchse gesehen. Damals auf der Wandernden Insel waren dies die ersten Tiere, die ich zu jagen gelernt habe.\n\nWenn Ihr dieselbe Herausforderung wie ich als junger Pandarenjäger erleben möchtet, dann begebt Euch Richtung Osten und legt Euch mit einer Meute Füchse an. Sie sind recht schlau und gerissen, also passt auf Euch auf.", sourceObjective = "Tötet 15 Schlaufüchse.", completion = "Gut gemacht. Ihr habt den Füchsen keine Chance gelassen. Ich werde mit Mr. Pleeb sprechen. Vielleicht kann er Euch noch eine Trophäe anfertigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30183] = { id = 30183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Pirscherjagd", description = "Tiger! Egal, welches Land ich bereise, diese Bestien mit Fangzähnen sind immer ein Thema. Und trotzdem hatte ich noch keine Gelegenheit, Jagd auf sie zu machen.\n\nLasst uns ein paar Tiger jagen. Ich gehe nach Osten und Ihr nach Westen. Ich glaube, ich habe einige in der Nähe der Staubrückenklamm gesehen. Ich wette, in der Nähe dieser Mushan halten sich jede Menge von ihnen auf.", sourceObjective = "Tötet 15 Schluchtpirscher.", progress = "Wie steht's mit Eurer Ausbeute?", completion = "Wahnsinn! Das nenne ich mal eine gute Ausbeute. Ich werde mit Mr. Pleeb sprechen. Vielleicht kann er aus dem besten Exemplar eine Trophäe für Euch anfertigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30184] = { id = 30184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mushanjagd: Rußhaut", description = "Mein Junge hier ist ein begabter Jäger... in Ausbildung. Jetzt soll er mal sehen, wie ein richtiger Nesingwary das macht!\n\nÖstlich von hier habe ich einen riesigen Mushan mit einer Haut so dunkel wie die Nacht selbst gesehen. Ich wette, die Bestie hat schon einige Jäger auf dem Gewissen.\n\nWenn Ihr also an der Großwildjagd interessiert seid, dann habt Ihr jetzt ein schönes Ziel.", sourceObjective = "Holt Euch Rußhauts Kopf.", progress = "Größer kann die Großwildjagd nun wirklich nicht werden.", completion = "Das nenne ich doch mal eine echte Jagdtrophäe.", sourceObjectiveStatus = "unverified-source-field" }
quests[30185] = { id = 30185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schildkrötenjagd", description = "Zugegeben, Schildkröten sind nicht gerade Großwild, aber sie können ganz schön gemein sein. Sie sind außerdem die perfekten Köder für die Großwildjagd!\n\nHabdich hat ein paar Aufzeichnungen gefunden, in denen steht, dass die Torjarigrube früher eine Opferstelle war. Das alte Reich hat da irgendetwas Komisches mit dem Wasser angestellt.\n\nWürde mich mal interessieren, was da so im Wasser schwimmt. Bringt mir ein paar frische Schildkrötenpanzer und trefft mich dann in der Grube.\n\nMal sehen, ob die alten Geschichten wahr sind.", sourceObjective = "Besorgt 5 intakte Schildkrötenpanzer.", progress = "Ich habe immer im Schatten meines großen Vaters gelebt. Aber von heute an werden sich die Leute auch an den Namen von Nesingwary Jr. erinnern!", completion = "Ich danke Euch. Das sollte mir einen Vorsprung vor meinem alten Herrn einbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30186] = { id = 30186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elterliche Fürsorge", description = "Wenn diese Aufzeichnungen stimmen, muss ich nur einen kleinen Tanz aufführen, um das große Ding aus der Tiefe heraufzubeschwören.\n\nUnd wenn es auftaucht, schnappen wir uns die Bestie und beweisen meinem Vater, dass wir echte Großwildjäger sind.", sourceObjective = "Besiegt Torjars Fluch.", progress = "Das nenne ich echte Großwildjagd.", completion = "Ihr habt meinen Sohn gerettet! Ich bin Euch unendlich dankbar. Bitte nehmt dies hier für Eure Heldentat.", sourceObjectiveStatus = "unverified-source-field" }
quests[30187] = { id = 30187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugausbildung: Der richtige Kurs", description = "Nun da Ihr die Grundlagen des Rennens erlernt habt, solltet Ihr Euch die Strecke ansehen.\n\nErkundet die Spitzen und sammelt von jedem der Kontrollpunkte eine Rennflagge ein.\n\nFliegt durch jede karierte Flagge hindurch, um sie einzusammeln.", sourceObjective = "Fliegt durch 10 Rennflaggen bei den Kontrollpunkten über der Nebelschleiersee.", progress = "Habt Ihr das Zeug dazu, teilzunehmen... und zu gewinnen?", completion = "Gut gemacht. Falls Ihr die Kontrollpunkte nicht gefunden hättet, wärt Ihr im Himmelsrennen wohl kaum erfolgreich gewesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30188] = { id = 30188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Himmel reiten", description = "Ich kann Euch nichts mehr beibringen, {name}.\n\nIhr habt Euch Eurer Schlange als würdig erwiesen.\n\nHeute werdet Ihr in unseren Orden aufgenommen. Seid Ihr bereit?", sourceObjective = "Tretet dem Orden der Wolkenschlange bei.", completion = "Heute verbrüdern wir uns.\n\nHerzlichen Glückwunsch zur Aufnahme in den Orden der Wolkenschlange. Reiten wir zusammen!", sourceObjectiveStatus = "unverified-source-field" }
quests[30189] = { id = 30189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein hübscher Apfel für Ella", progress = "Wie geht's Euch denn so, {name}?", completion = "Was? Für mich?\n\nSo einen hübschen Apfel sollte man nicht alleine essen.\n\nHier, bitte nehmt eine Hälfte." }
quests[30190] = { id = 30190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreiste Geister", description = "Diese Geister schon wieder! Ich hasse sie! Wir müssen sie aufhalten, bevor jemand zu Schaden kommt oder sie das halbe Dorf niederbrennen!\n\nWenn Ihr einen von diesen Plagegeistern seht, dann löscht ihn aus!", sourceObjective = "Löscht 8 Schieferhautunruhestifter aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[30191] = { id = 30191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg von unserem Bier", description = "Jemand hat oben am südlichen Hang etwas Bier draußen rumstehen lassen. Und jetzt haben die Geister unser Bräu zu schätzen gelernt. Sie treiben sich schon den ganzen Morgen im Ort herum und stehlen alle Fässer, die sie kriegen können.\n\nBringt alles zurück, was Ihr finden könnt. Ein Pandarenarbeiter ohne Bier ist... nicht sehr produktiv. Wir müssen die Männer bei Laune halten.", sourceObjective = "Bergt 10 gestohlene Fässer von Nebelhauch.", sourceObjectiveStatus = "unverified-source-field" }
quests[30192] = { id = 30192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es brennt!", description = "Ich weiß ja nicht, ob Ihr es bemerkt habt, aber mein Dorf brennt...\n\nDie Geister haben begonnen, die Kohlengrills umzuwerfen! Sie werden noch das ganze Dorf in Brand setzen!\n\nBitte helft uns! Tretet alle Feuer aus, die Ihr seht!", sourceObjective = "Tretet 30 Kohlengrillfeuer aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[30193] = { id = 30193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lecker Gazelle", description = "Wer hart arbeitet, verdient eine herzhafte Mahlzeit. Aber ich habe kein gutes Fleisch mehr!\n\nKönntet Ihr in den Wald ziehen und mir etwas frisches Gazellenfleisch besorgen?", sourceObjective = "Besorgt 10 Stücke Schönlandgazellenfleisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[30194] = { id = 30194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stürmische Ausbreitung", description = "Die Dorfbewohner haben heute morgen schon wieder ein Yak an einen dieser Donnermaulwölfe von der anderen Flussseite verloren. Diese Wölfe werden immer dreister.\n\nDas ist ein sicheres Zeichen dafür, dass ihre Population zu groß für dieses Tal wird. Wir müssen wieder einmal ihre Anzahl dezimieren.\n\nWenn Ihr diesen Auftrag annehmen möchtet, könnt Ihr Euch meiner Dankbarkeit gewiss sein.", sourceObjective = "Tötet 8 Donnermaulwölfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[30195] = { id = 30195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Blüten", description = "Würdet Ihr einem bescheidenen Händler einen Gefallen erweisen? Ich muss meinen Bestand an Ewigen Blüten auffrischen. Sie wachsen in den nahe gelegenen Wäldern.\n\nWäret Ihr vielleicht so freundlich, mir zu helfen?", sourceObjective = "Sammelt 10 Ewige Blüten.", sourceObjectiveStatus = "unverified-source-field" }
quests[30196] = { id = 30196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mjampignons!", description = "Der Aufbau eines neuen Dorfes scheint den Arbeitern mächtig Appetit zu machen!\n\nIch habe einen herzhaften Eintopf vorbereitet, aber dazu brauche ich noch ein paar Mjampignons von der Tu-Shen-Begräbnisstätte im Osten. Leider treiben dort ein paar aufgebrachte Geister ihr Unwesen und ich bin nicht gerade eine Kämpfernatur.\n\nKönntet Ihr mir ein paar Mjampignons mitnehmen, wenn Ihr heute die Begräbnisstätte aufsuchen solltet?", sourceObjective = "Sammelt 12 Mjampignons zusammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30197] = { id = 30197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wagenfahrt", description = "Im Tal ist es heute Morgen ruhig gewesen. Ich schicke Rook mit einem Wagen voller Waren nach XXX. Ihr solltet ihn begleiten.", sourceObjective = "Fahrt mit dem Wagen nach XXX.", sourceObjectiveStatus = "unverified-source-field" }
quests[30200] = { id = 30200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Netz der Glut", description = "Als Teil ihrer Ausbildung mussten die Schüler die Spinnen in den Ruinen erledigen, aber jetzt haben wir sie direkt zur Mogufront entsandt. Und seitdem sind die Spinnen außer Kontrolle.\n\nKönntet Ihr Euch um sie kümmern?", sourceObjective = "Tötet 8 Glutnetzspinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30204] = { id = 30204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht drauftreten!", description = "Ich gebe es zu: Diese Spinnen ekeln mich an. Insbesondere ihre Eiersäcke, die sie überall liegen lassen. Immer wenn ich ungewollt auf diese Dinger drauftrete, kriechen da diese Spinnlinge raus. Wenn ich nur daran denke, bekomme ich eine Gänsehaut.\n\nIch möchte, dass Ihr sie verbrennt. Und zwar restlos alle!", sourceObjective = "Tötet 50 Glutnetzspinnlinge. Verwendet Kuns Fackel, um sie noch in den Brutsäcken zu verbrennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30205] = { id = 30205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runensperre", description = "Hallo, <mein Freund/meine Liebe>.\n\nEiner von Levens Leuten hat mir von einem Moguartefakt in den östlichen Ruinen erzählt. Aber er wusste nicht, wie man an dieses Artefakt herankommt. Ich vermute ja, dass es durch eine Runensperre gesichert ist.\n\nWenn Ihr Euch dem Artefakt nähert, solltet Ihr vier Runen in der Nähe finden, die die Sperre nach ihrer Aktivierung aufheben. Ich wäre Euch wirklich sehr verbunden, wenn Ihr mir dieses Artefakt bringen könntet.", sourceObjective = "Bergt das uralte Moguartefakt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30206] = { id = 30206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runen in den Ruinen", description = "In den Ruinenwänden selbst befinden sich wertvolle Runensteine, für die wir im östlichen Tal gute Verwendung hätten.\n\nWäret Ihr so freundlich, mir ein paar davon mitzubringen, wenn Ihr Euch in den Ruinen aufhaltet?", sourceObjective = "Sammelt 12 Guo-Lai-Runensteine zusammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30207] = { id = 30207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: 1. Platz" }
quests[30208] = { id = 30208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: 2. Platz" }
quests[30209] = { id = 30209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: 3. Platz" }
quests[30210] = { id = 30210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: 4. Platz" }
quests[30211] = { id = 30211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: 5. Platz" }
quests[30212] = { id = 30212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: 6. Platz" }
quests[30225] = { id = 30225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod der Glutnetzmatriarchin", description = "Mein lieber Kun hat heute morgen noch mehr Spinnen aus den Guo-Lai-Hallen kommen sehen. Und als er sich das näher anschauen wollte, ist er da drinnen auf eine weitere Spinnenmatriarchin gestoßen.\n\nIch möchte, dass Ihr sie umbringt.", sourceObjective = "Tötet Blutspitz, die Glutnetzmatriarchin.", sourceObjectiveStatus = "unverified-source-field" }
quests[30226] = { id = 30226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blut erhebt sich", description = "Eine kleine Gruppe Mogu wurde auf der Ruinenerhebung im Norden gesichtet.\n\nVernichtet sie.", sourceObjective = "Tötet 8 Shao-Tien-Mogu auf der Ruinenerhebung.", sourceObjectiveStatus = "unverified-source-field" }
quests[30227] = { id = 30227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wulon der Granitwächter", description = "Eine der Qilenstatuen in den Guo-Lai-Hallen ist zum Leben erwacht und hätte fast meinen lieben Kun getötet. So etwas ertrage ich einfach nicht! Niemand darf meinem Kun etwas antun.\n\nIch möchte, dass Ihr dort hineinstürmt und das Ding in Tausend Stücke schlagt. Ich würde es ja selbst tun, aber ich muss mich um die Wunden meines Liebsten kümmern.", sourceObjective = "Tötet Wulon den Granitwächter.", sourceObjectiveStatus = "unverified-source-field" }
quests[30228] = { id = 30228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unruhe unter den Unruhestiftern stiften", description = "Die Waldgeister sind zurück. Ich möchte, dass Ihr sie tötet, bevor sie noch mehr Ärger machen.", sourceObjective = "Tötet 8 Steinborkentrickster.", sourceObjectiveStatus = "unverified-source-field" }
quests[30229] = { id = 30229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Gefahr", description = "Ich muss mich für meine strengen Worte von vorhin entschuldigen. Es war möglicherweise richtig von Dezco, abzuwarten, um mit vereinten Kräften weiter nach Westen zu ziehen.\n\nDie Mogu haben uns bei der Erkundung der Ruinen westlich von hier einen schweren Schlag versetzt. Sie haben uns mithilfe von Beschwörungsportalen und dunkler Magie in einen Hinterhalt gelockt. Ich habe seit der Scherbenwelt solch niederträchtige Zauberei nicht mehr gesehen.\n\nWir müssen unsere Kräfte sammeln. Geht nach Westen, tötet ihre Beschwörer und durchtrennt ihre Versorgungslinien.", sourceObjective = "Tötet 8 Korjanieroberer.", completion = "Nun da ihre Nachschublinien unterbrochen sind, können wir anfangen, eine Offensive gegen ihren Obersten Eroberer auf die Beine zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30230] = { id = 30230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erneute Zurückeroberung", sourceObjective = "Beschafft 10 Moguartefakte.", progress = "Jedes Artefakt in unserem Besitz ist eine Waffe weniger in den Händen der Mogu.", completion = "Gut gemacht, {name}. Ihr habt dem Kind das Schwert aus der Hand genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30231] = { id = 30231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pomfruchtlieferung", description = "Ich brauche mehr Pomfrucht! Könntet Ihr mir bitte einige von den Bäumen schütteln?\n\nHier, nehmt das. Das benutze ich immer zum Ernten. Es beschleunigt die Angelegenheit, wenn die Früchte Euch entgegenkommen!", sourceObjective = "Erntet 12 Pomfrüchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[30232] = { id = 30232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitze Federn", description = "Die Falkenpopulation im Tal hat stark zugenommen. Dies ist eine gute Gelegenheit für unsere Pfeilmacher, denn wir brauchen jede Menge Federn, um die Bogenschützen auf der Mauer weiter mit Pfeilen auszustatten.\n\nKönntet Ihr vielleicht unseren Leuten beim Sammeln dieser Federn helfen?", sourceObjective = "Sammelt 80 seidige Federn.", sourceObjectiveStatus = "unverified-source-field" }
quests[30233] = { id = 30233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knackzahn", description = "Hallo! Also, ich stecke sozusagen in der Klemme ... Mir fällt nur EIN guter Name für einen Wolf ein... Na, gespannt? Genau: Knackzahn! Ganz schön gewitzt, nicht wahr? Aber jetzt treiben sich gleich ZWEI große, böse Wölfe in den Wäldern herum. Und das bringt mich ganz durcheinander.\n\nIch möchte, dass Ihr einen von ihnen tötet, damit ich den Namen neu vergeben kann. Ist doch ganz einfach, oder? Besonders für jemanden mit so unglaublichen Fähigkeiten wie Euch.\n\nAlso, nehmt Ihr an? Ich hoffe doch sehr!", sourceObjective = "Tötet Knackzahn.", sourceObjectiveStatus = "unverified-source-field" }
quests[30234] = { id = 30234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zangenkiefer", description = "Zangenkiefer! Das klingt doch nach purer, roher Gewalt, nicht wahr? Den Namen habe ich selbst ersonnen. Und ich finde ihn sehr passend. Ich habe nämlich stundenlang versucht, ihm meinen Stab abzunehmen, aber er wollte einfach nicht loslassen!\n\nAlso gut, vielleicht waren es auch nur einige Sekunden. Ich erzähle Freunden lieber die Wahrheit. Auch wenn das meine Geschichten weniger aufregend klingen lässt.\n\nAber wäret Ihr vielleicht so freundlich, Eure nahezu allmächtigen Kräfte zu entfesseln, um diesem Krokilisken den Stab zu entreißen und ihn mir wiederzubringen? Und zwar am besten in einem Stück!", sourceObjective = "Tötet Zangenkiefer und bringt Rens Langstab zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[30235] = { id = 30235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krakwall", description = "Kwall ist ein sehr mächtiger und sehr alter Wassergeist, auch wenn seine kindische Art nicht darauf schließen lässt.\n\nHeute morgen hätte Kwall fast sieben Leute in der Schenke getötet, als er nur aus Spaß ein paar Wasserfässer explodieren ließ.\n\nSo lange irgendwo Wasser fließt, ist Kwall zugegen. Man kann ihn nie endgültig ausschalten. Aber wir können ihm zeigen, dass wir seine gefährlichen Scherze nicht gutheißen.\n\nKönntet Ihr ihm diese Botschaft im Namen des Dorfes überbringen?", sourceObjective = "Besiegt Kwall, den Geist der Nebelfälle.", sourceObjectiveStatus = "unverified-source-field" }
quests[30236] = { id = 30236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aetha", description = "Anscheinend hat Aetha wieder einmal das Vieh freigelassen und es in den Fluss getrieben. Der Bürgermeister hat uns aufgetragen, ihr deutlich zu machen, dass solcherlei Schabernack gänzlich unerwünscht ist.\n\nWäret Ihr vielleicht so freundlich, Euch zum Hügelkamm oberhalb des Dorfes zu begeben und ihr eine Lektion zu erteilen? Ihr könnt sie nicht unwiederbringlich töten, aber zumindest könnt Ihr sie für eine Weile vertreiben. Das sollte ihr eine deutliche Warnung sein.", sourceObjective = "Besiegt Aetha, den Geist der Goldenen Winde.", sourceObjectiveStatus = "unverified-source-field" }
quests[30237] = { id = 30237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ewige Aufstand der Pandaren", description = "An der Tu-Shen-Begräbnisstätte im Osten tragen die Geister der uralten Mogu und die Geister unserer Pandarenvorfahren einen ewigen Kampf aus der Zeit des Pandarenaufstands aus. Seit die Mogu in das Tal zurückgekehrt sind, scheinen die Geister keine Ruhe zu finden.\n\nWenn Ihr uns helfen wollt, dann begebt Euch bitte zum Friedhof und besiegt die uralten Mogugeister noch einmal. Vielleicht finden dann unsere Vorfahren endlich Frieden.", sourceObjective = "Tötet 8 uralte Mogugeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[30238] = { id = 30238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre, wem Ehre gebührt", description = "Die Geister unserer Vorfahren tragen erneut eine ihrer früheren Schlachten an der Tu-Shen-Begräbnisstätte im Osten aus.\n\n{race}, ich möchte Euch um einen Gefallen bitten: Erweist bitte ihren Grabsteine die Ehre. Erinnert sie daran, dass sie auch nach all diesen Jahren noch Respekt erfahren und sie es verdient haben, in Frieden zu ruhen.", sourceObjective = "Erweist 6 Pandarengrabsteinen die Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[30239] = { id = 30239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lao-Fe der Sklavenbinder", description = "Aus der oberen Höhle der Tu-Shen-Begräbnisstätte hört man das Geschrei von Lao-Fe dem Sklavenbinder.\n\nDurch seine Vernichtung sollte der Sieg der Geister der Pandarenmönche gewährleistet sein.", sourceObjective = "Tötet den Geist von Lao-Fe dem Sklavenbinder.", sourceObjectiveStatus = "unverified-source-field" }
quests[30240] = { id = 30240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlebensring: Flammen", description = "Dies ist eine der Herausforderungen, die ich meinen Kriegern stelle, damit sie stark und flink auf den Beinen bleiben. Mal sehen, wie Ihr Euch haltet.\n\nÜberlebt 60 Sekunden im Ring, ohne hinausgestoßen zu werden. Macht Euch auf alles gefasst!", sourceObjective = "Betretet den Überlebensring und überlebt 60 Sekunden lang, ohne hinausgestoßen zu werden.", progress = "Die konstante Gefahr im Ring bereitet uns auf die echten Kämpfe um Leben und Tod vor, die wir jenseits der Mauer führen müssen.", completion = "Nicht schlecht. Überhaupt nicht schlecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[30241] = { id = 30241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnung an Steinpflug", description = "So viel Tod. Und wenn man Botschafter Hans Geschichten von den Mantis Glauben schenken kann, ist es noch längst nicht zu Ende.\n\nWir müssen helfen. Wir müssen unseren Teil zur Rettung von Leben beitragen.\n\nReist nach Steinpflug. Warnt sie vor dem bevorstehenden Angriff der Mantis.\n\nIch werde mit den Kräften, die ich noch aufbringen kann, zu Euch stoßen, nachdem ich Kors Leichnam zur letzten Ruhe gebettet habe.", sourceObjective = "Reist nach Steinpflug im Tal der Vier Winde.", completion = "Mantis aus dem Süden? Das ist kein guter Tag.", sourceObjectiveStatus = "unverified-source-field" }
quests[30242] = { id = 30242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlebensring: Klingen", description = "Dies ist eine der Herausforderungen, die ich meinen Kriegern stelle, damit sie stark und flink auf den Beinen bleiben. Mal sehen, wie Ihr Euch haltet.\n\nÜberlebt 60 Sekunden im Ring, ohne hinausgestoßen zu werden. Bleibt auf den Beinen.", sourceObjective = "Betretet den Überlebensring und überlebt 60 Sekunden lang, ohne hinausgestoßen zu werden.", progress = "Die konstante Gefahr im Ring bereitet uns auf die echten Kämpfe um Leben und Tod vor, die wir jenseits der Mauer führen müssen.", completion = "Nicht schlecht. Überhaupt nicht schlecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[30243] = { id = 30243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frittierte Mantis", description = "Die Mantis greifen schon wieder an und wir sind auf der Mauer etwas unterbesetzt. In der Hoffnung auf Eure Hilfsbereitschaft habe ich schon einmal einen der spaßigeren Posten für Euch reserviert: das heiße Öl!\n\nDas ist etwas brutaler und etwas weniger skandalös, als es klingt.\n\nEigentlich ist es ganz einfach: Geht rauf auf die Mauer, findet eine der Stationen mit heißem Öl und kippt es auf alle Mantis, die gegen die Mauer anstürmen. Eine wirklich sehr effektive Methode.", sourceObjective = "Verwendet einen Kessel mit heißem Öl, um 80 Mantis am Tor der Untergehenden Sonne zu töten.", progress = "Das Saubermachen ist viel härtere Arbeit. Aber glücklicherweise habt Ihr damit nichts zu tun.", completion = "Ihr habt den Mantis-Truppen verheerenden Schaden zugefügt. Die Mauerverteidiger sollten die Lage jetzt unter Kontrolle bringen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[30244] = { id = 30244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangenbändigung", description = "Es sind Mantis auf die Mauer gelangt. Die Verteidiger auf der Brustwehr haben nach Hilfe gerufen.", sourceObjective = "Tötet 10 Krik'thik-Mantis am Tor der Untergehenden Sonne.", sourceObjectiveStatus = "unverified-source-field" }
quests[30245] = { id = 30245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene Späher", description = "Wir haben einige Späher in Richtung der Fünf Schwestern im Norden entsandt, damit sie herausfinden, was für ein Moguanführer aufgetaucht ist, um die feindlichen Truppen durch das Tal zu führen. Es sind nur wenige Späher zurückgekehrt.\n\nIch würde gern hoffen, dass sie einfach zu viel Bier getrunken oder zu viel Spaß mit einigen Pandarenmädchen haben. Aber sie könnten auch in großen Schwierigkeiten stecken.\n\nKönntet Ihr Ausschau nach den Spähern halten? Und fragt sie auch gleich nach Informationen über diesen Anführer, bitte.", sourceObjective = "Sichert die Berichte von 3 Shado-Pan-Spähern.", sourceObjectiveStatus = "unverified-source-field" }
quests[30246] = { id = 30246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantis auf der Brustwehr", description = "Einige der Mantis haben es bis auf die oberste Ebene der Mauer geschafft. Wenn es zu viele von ihnen werden, drohen unsere Soldaten dort überrannt zu werden.\n\nIch möchte, dass Ihr Euch nach dort oben begebt und alle Feinde erledigt, die durchgebrochen sind.", sourceObjective = "Tötet 10 Krik'thik-Mantis auf der obersten Ebene des Tors der Untergehenden Sonne.", sourceObjectiveStatus = "unverified-source-field" }
quests[30247] = { id = 30247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rollclub: Tal der Ewigen Blüten", description = "Folgt den Flaggen. Erreicht die Kontrollpunkte. Umrundet den Bogen. Kehrt zu mir zurück, bevor die Zeit abgelaufen ist.\n\nGebt mir Bescheid, wenn Ihr bereit seid.", sourceObjective = "Schließt den Rollkurs des Tals der Ewigen Blüten ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[30248] = { id = 30248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtzeit", description = "Einige Späher haben den auf sich allein gestellten Shao-Tien-Imperion am Nordende der Mauer ausfindig gemacht.\n\nAnji Herbstlicht hat Euren Auftrag ganz klar definiert: Findet den Anführer und tötet ihn.", sourceObjective = "Tötet Bai-Jin den Schlächter.", sourceObjectiveStatus = "unverified-source-field" }
quests[30249] = { id = 30249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter der Untergehenden Sonne", description = "Eine riesige Bestie hat sich unter das Tor durch gegraben und ist im Hof aufgetaucht. Die Verteidiger brauchen Eure Hilfe!", sourceObjective = "Tötet Kri'chon den Leichenhäscher.", sourceObjectiveStatus = "unverified-source-field" }
quests[30250] = { id = 30250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlebensring: Donner", description = "Dies ist eine der Herausforderungen, die ich meinen Kriegern in Friedenszeiten stelle, damit sie stark und flink auf den Beinen bleiben. Mal sehen, wie Ihr Euch haltet.\n\nÜberlebt 90 Sekunden im Ring, ohne hinausgestoßen zu werden. Bleibt auf den Beinen.", sourceObjective = "Betretet den Überlebensring und überlebt 90 Sekunden lang, ohne hinausgestoßen zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[30251] = { id = 30251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyraxxis, der Schwarmfürst der Krik'thik", description = "Ein riesiger Mantis ist in den inneren Bereich der Mauer eingedrungen. Ohne Eure Hilfe werden die Verteidiger kaum mit ihm fertig.", sourceObjective = "Tötet Vyraxxis, den Schwarm-Herrscher der Krik'thik.", sourceObjectiveStatus = "unverified-source-field" }
quests[30252] = { id = 30252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine helfende Hand", description = "Ich drücke und schiebe schon den ganzen Morgen an ihnen herum und hämmere auf sie ein, aber es ist hoffnungslos.\n\nDiese Felsbrocken bewegen sich nicht vom Fleck!\n\n\"Das ist doch ein Klacks\", hat Großvater gesagt. \"Landwirtschaft ist so einfach wie atmen!\", sagte er. Für ihn mag das so sein, aber nicht für mich!\n\nWie soll ich bei dieser LANDWIRTSCHAFT Erfolg haben, wenn ich mein Land noch nicht mal zur Bestellung freiräumen kann?\n\nHe, Moment mal. Ihr seht aus, als hättet Ihr ordentlich Muckis.\n\nWürdet Ihr mir helfen? Nur bis ich wieder zu Atem komme.", sourceObjective = "Zerstört 8 unnachgiebige Felsen.", completion = "Was? Ihr habt die Steine beiseitegeschafft? Das ist ja wunderbar!\n\nVielleicht kann ich jetzt ja endlich etwas auf diesem Acker anbauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[30253] = { id = 30253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Familienhof", description = "Ha-Habt Ihr das gehört?\n\nMan könnte meinen, sie wollen mich gar nicht hier haben. Als... wäre ich nicht gut genug.\n\nSicher, ich habe noch nie einen Hof geführt, aber ich weiß sehr wohl, wie man etwas sät oder eine Steckrübe erntet.\n\n<Bauer Yoons Augen leuchten auf.>\n\nWisst Ihr was? Ich werde ihnen zeigen, dass auch ich ein Meisterbauer werden kann!\n\nIch werde diesen Hof hier zum profitabelsten Hof im ganzen Tal machen!\n\nAber für einen einzelnen Pandaren ist das zu viel Arbeit. Also, würdet Ihr mir helfen?", sourceObjective = "Schließt Euch Bauer Yoon an.", sourceObjectiveStatus = "unverified-source-field" }
quests[30254] = { id = 30254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agrikultur II: Pflügen und Pflanzen", description = "So, jetzt ist es an der Zeit, die Samen einzupflanzen.\n\nAls erstes müssen wir dazu den Boden vorbereiten! Ihr müsst ihn pflügen, damit die Samen auskeimen können.\n\nPflügt die zwei Ackerflächen da drüben und pflanzt dann die Samen ein.", sourceObjective = "Pflügt 2 Flächen ungepflügtes Erdreich um, damit daraus gepflügtes Erdreich wird. Pflanzt dann auf 2 Flächen die Simp-L-WAX-Grünkohlsamen ein.", completion = "Gut gemacht.\n\nHabt Ihr gesehen, wie sich sofort Wurzeln gebildet haben? Das ist einer der Gründe, warum dieses Tal ideal für die Landwirtschaft geschaffen ist. Irgendetwas in diesem Boden hier lässt die Pflanzen wachsen wie verrückt!\n\nAber die Arbeit ist damit noch nicht erledigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30255] = { id = 30255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agrikultur III: Hegen und Pflegen", description = "Mein Großvater hat immer gesagt: \"Yoonie, Kohlköpfe sind wie Frauen: Wenn man sie ignoriert, verwelken sie. Aber wenn man sie hegt und pflegt, werden sie rund und proper und man kann ihnen eine Schleife umbinden und sie mit auf den Markt nehmen und stolz den Leuten zur Schau stellen und...\" Hey, schaut mich nicht so an! Das waren halt andere Zeiten damals!\n\nDer Punkt ist: Jetzt, wo unsere Kohlköpfe Wurzeln geschlagen haben, benötigen sie Pflege! Sie sehen heute etwas trocken aus, also müsst Ihr sie wässern.\n\nHier ist die alte Gießkanne meines Großvaters. Sie ist immer in der Nähe des Feldes, wenn Ihr sie braucht.", sourceObjective = "Verwendet die rostige Gießkanne, um 2 ausgetrocknete Simp-L-WAX-Grünkohlköpfe auf dem Gehöft Sonnensang zu wässern.", completion = "Sehr gut! Die Kohlköpfe sehen gesund und gepflegt aus!\n\nHeute waren sie nur durstig, aber man weiß nie, was sie als Nächstes benötigen. Behaltet die Pflanzen immer im Auge und kümmert Euch gut um sie.\n\nMein Großvater hat mir jede Menge Ratschläge mitgegeben. Wenn Ihr Euch also mal bezüglich der Pflege unsicher seid, könnt Ihr mich immer fragen!\n\nAber bitte nur Fragen zur Landwirtschaft...", sourceObjectiveStatus = "unverified-source-field" }
quests[30256] = { id = 30256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agrikultur IV: Ernten", description = "Jetzt ist es an der Zeit, dass wir die Früchte unserer harten Arbeit ernten! Normalerweise müssten wir ja einen Tag warten bis zur Ernte dieser Pflanzen.\n\nAber glücklicherweise lassen diese Samen, die wir von Grünfeld bekommen haben, die Pflanzen EXTRA SCHNELL wachsen. Der Ertrag wird nicht allzu hoch sein, aber trotzdem können Nachwuchsbauern so den ganzen Prozess kennenlernen.\n\nUnsere Kohlköpfe müssten jetzt erntereif sein. Und ich überlasse natürlich Euch diese Ehre!", sourceObjective = "Erntet 2 Simp-L-WAX-Grünkohlköpfe von Eurem Feld und bringt sie zu Bauer Yoon auf dem Gehöft Sonnensang.", progress = "Jetzt sieh sich doch einer mal diese... äh... Dinger an. Wie nennt man so was noch mal? Ach ja: Prachtexemplare!\n\nWas für Prachtexemplare!\n\nSo langsam klappt es ja mit der Landwirtschaft.", completion = "So, das waren die Grundlagen!\n\nBoden pflügen, Samen pflanzen, die Schösslinge hegen und auf das Ergebnis warten!\n\nHeute war es einfach, aber lasst Euch nicht blenden: Mein Großvater hat mir alle möglichen verrückten Dinge über das Gehöft Sonnensang erzählt.\n\nDie Landwirtschaft besteht nicht nur aus Riesenrüben und Rosen, wisst Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[30257] = { id = 30257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernen und Wachsen V: Halbhügelmarkt", description = "Na schön. Der ganze Anbau war nur zum Üben!\n\nSeid Ihr bereit, Euch an der echten Sache zu versuchen?\n\nEs gibt da eine Dame namens Gina Lehmkrall, die den Halbhügelmarkt auf der anderen Straßenseite im Süden leitet.\n\nIch höre, sie will Gemüse kaufen. Bei Eurer ersten Begegnung solltet Ihr nicht mit leeren Händen auftauchen.\n\nWarum seht Ihr Euch nicht auf dem Gehöft um, ob sich irgendwelche Gegenstände dort verbergen?\n\nVielleicht finden wir ja ein schönes Geschenk für unsere neue Nachbarin!", sourceObjective = "Untersucht die dunkle Erde unter dem Haus des Bauern Yoon und bringt dann ein Geschenk zu Gina Lehmkrall auf dem Halbhügelmarkt.", progress = "Hey, habe ich Euer Gesicht hier nicht schon mal gesehen? Wie heißt Ihr?", completion = "Meine Güte, eine Sumpflilie!\n\nWoher wusstet Ihr, dass das meine Lieblingsblume ist? Ihr seid ganz nach meinem Geschmack, Fremder.\n\nDanke!", sourceObjectiveStatus = "unverified-source-field" }
quests[30258] = { id = 30258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mung-Mungs Stimme I: Das Problem eines Ho-zen", description = "Ich habe darüber nachgedacht, wie ich bei den Ackerbauern einen guten Eindruck machen kann, {name}.\n\nDer Bund der Ackerbauern nimmt ja jedes Jahr neue Mitglieder auf, und der Wahlrat besteht aus fünf Leuten.\n\nGinas Stimme haben wir schon, vor den anderen vier Mitgliedern des Rats müssen wir uns aber noch bewähren.\n\nWarum geht Ihr nicht rüber und begrüßt Mung-Mung? Er arbeitet auf Herrn Lehmkralls Bauernhof im Nordwesten.", sourceObjective = "Sprecht mit Mung-Mung bei Haohan Lehmkralls Haus im Tal der Vier Winde.", completion = "Ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[30259] = { id = 30259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mung-Mungs Stimme II: Bis ins Mark verdorben", description = "Die Shed-Ling sind wieder da!\n\nHaben Herrn Lehmkralls Karotten angeknabbert. Ruinieren seine Ernte. Und wer muss es ausbaden? Mung-Mung, genau!\n\nSammel schnell die angenagten Karotten auf, bevor Herr Lehmkrall sie sieht. Sie sind über die Felder im Südwesten verstreut und unterirdisch, in den Tunneln der Shed-Ling.\n\nSonst bekommt Mung-Mung großen Ärger.\n\nTust du das für mich?", sourceObjective = "Sammelt 10 angenagte Karotten auf.", progress = "Ich hab' hier keine angenagten Karotten gesehen und du auch nich'. Herr Lehmkrall wird nie was davon mitkriegen, ja?", completion = "Was soll das heißen, kein Shed-Ling hat sie angefressen? Zu kleine Bissspuren? WAS? Wer sonst macht denn so was?", sourceObjectiveStatus = "unverified-source-field" }
quests[30260] = { id = 30260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Hof pflegen I: Das Unkraut", description = "Hey {name}, ich habe in letzter Zeit darüber nachgedacht, meinen Hof zu erweitern.\n\nSeht Ihr diese Fläche dort, die mit Unkraut überwuchert ist? Wenn wir das beseitigen, könnten wir dieses Land für den Anbau verwenden.\n\nIch habe gehört, es gibt einen Bauer namens Gai Lan, der etwas von Unkrautvernichtung versteht.\n\nSein Hof ist im Westen. Redet mit ihm - vielleicht hilft er uns.", sourceObjective = "Redet mit Gai Lan im Kernland im Tal der Vier Winde.", completion = "Oh ja, Bauer Yoon. Ich habe ihn in der Stadt gesehen.\n\nScheint ein anständiger Bursche zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[30261] = { id = 30261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rollclub: Schlangenrücken", description = "Erreicht so schnell wie irgend möglich den Fuß der Mauer.\n\nSprecht mich an, wenn Ihr bereit seid, loszurollen.", sourceObjective = "Schließt die Rollstrecke des Schlangenrückens ab.", progress = "Bereit, loszurollen?", completion = "Ich glaube nicht, dass sie das beim Bau der Mauer als Nutzungsmöglichkeit in Erwägung gezogen haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[30263] = { id = 30263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Wald säubern", description = "Die Shao-Tien sind in Bewegung. Die meisten haben sich nach ihrer letzten Niederlage in die Winterastlichtung zurückgezogen. Wir sollten den Vorteil nutzen.\n\nTragt den Kampf zu diesen Mogu in der Lichtung im Nordwesten. Wir sollten ihnen keine Minute der Ruhe gönnen, solange sie sich hier im Tal befinden.", sourceObjective = "Tötet 6 Mogu der Shao-Tien in der Winterastlichtung.", sourceObjectiveStatus = "unverified-source-field" }
quests[30264] = { id = 30264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind vor den Toren", description = "Die Mantistruppen bestürmen die Mauer. Ich habe ein paar Himmelsschlangen angefordert, um sie aus der Luft anzugreifen.\n\nWäret Ihr bereit, eine von ihnen zu lenken?", sourceObjective = "Vernichtet mithilfe einer Shado-Pan-Himmelsschlange 60 Angreifer der Krik'thik, 3 Kriegswagen der Krik'thik und 3 Katapulte der Krik'thik.", sourceObjectiveStatus = "unverified-source-field" }
quests[30265] = { id = 30265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Funkeln im Auge", description = "Ich habe lange in das Wasser geblickt und über das Leben, die Liebe und all die schönen Dinge sinniert, als ich plötzlich ein Glitzern im Wasser bemerkte. Und das waren nicht etwa die Reflexionen meiner strahlenden Persönlichkeit, sondern tatsächlich ein paar glitzernde Objekte da unten! Sicher etwas Wertvolles.\n\nWürdet Ihr vielleicht in die Tiefen hinabtauchen, um den See seiner glitzernden Geheimnisse zu berauben? Oh, bitte!", sourceObjective = "Bergt 8 Glitzerrubine.", sourceObjectiveStatus = "unverified-source-field" }
quests[30266] = { id = 30266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmel voller Blut", description = "Wir haben im oberen Bereich der Türme an den Flanken des Haupttors Kanonen platziert. Sie sind unsere beste Waffe, um die fliegenden Mantis daran zu hindern, die Mauer zu überfliegen. Und genau das versuchen sie gerade wieder.\n\nIch glaube, Ihr seid nun an der Reihe, {name}.", sourceObjective = "Tötet 30 Drohnen der Krik'thik mit einer Kanone am Tor der Untergehenden Sonne.", completion = "Eure Schützentalente sind beachtlich, {class}. Daran werde ich mich erinnern, wenn sich wieder einmal Feinde aus der Luft nähern.", sourceObjectiveStatus = "unverified-source-field" }
quests[30267] = { id = 30267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anglerträume", description = "Ich liebe es zu angeln. Der Spaß wäre jedoch wesentlich größer, wenn ich meine Köder hätte. Die hat aber meine Frau Rin wegen eines... eines Missverständnisses weggeworfen.\n\n<Lichtungswirker Lang seufzt.>\n\nSoll etwa ein ganzer Angeltag wegen einer winzigen ehelichen Meinungsverschiedenheit verdorben sein? Nein! Alles, was ich brauche, sind ein paar Insekten und Federn - und diese Lichtung ist voll von beidem.\n\nWürdet Ihr einem Angler vielleicht helfen?", sourceObjective = "Besorgt 18 Lichtungsglühwürmer und 5 spindeldürre Blutfedern.", progress = "Ich sehe es nicht ein, auf das Angeln zu verzichten. Das ist mein Leben!", completion = "Endlich jemand, der mich versteht. Angeln ist doch das Einzige, was zählt, oder?\n\nVielleicht sollte ich Neu-Cifera verlassen... Einfach meinen Kram packen und mich den Anglern unten im Süden anschließen. Natürlich könnte ich meine Familie nicht zurücklassen...\n\nAber trotzdem... Ein Pandaren kann doch auch mal träumen, stimmt's?", sourceObjectiveStatus = "unverified-source-field" }
quests[30268] = { id = 30268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Düsterfieber", description = "Seht genau hin. Der Fluss in der Nähe wimmelt von diesen Schlangen. Ihr Gift führt zu einem Zustand, den die Einheimischen \"das Düsterfieber\" nennen.\n\nEin paar Flüchtlinge wurden gebissen, als sie aus dem Tempel flohen, und zeigen bereits erste Symptome: Übelkeit, Erbrechen und Schweißausbrüche. Der Körper scheidet jegliche Flüssigkeit aus, was zu Dehydrierung und möglicherweise zum Tod führt.\n\nWir verabreichen so schnell wie möglich Gegengift, aber wir brauchen noch mehr Giftdrüsen. Haltet Euch nicht damit auf, die Drüsen selbst zu entfernen - bringt einfach den ganzen Kopf mit.", sourceObjective = "Sammelt 6 Düsterschuppenköpfe von Angreifern der Düsterschuppen im Krasarang.", progress = "<Anduin konzentriert sich aufmerksam auf seine Hände und schneidet schnell die Giftdrüsen aus den Schlangen.>\n\nIm Rachen... fünf Zentimeter hinter der zweiten Reihe Fangzähne...", completion = "Danke, {class}. Ich wusste, dass Ihr zäh genug seid, um damit fertigzuwerden.\n\nWenn ich mir so die Geräusche anhöre, die diese Flüchtlinge von sich geben, würde ich das Düsterfieber nicht meinem ärgsten Feind wünschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30269] = { id = 30269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsichere Passage", description = "Wie wir im Tempel immer sagen: \"Kämpft nie gegen einen Tiger, wenn Ihr einen Ho-zen im Nacken habt.\"\n\nWir werden uns um das Sha kümmern, aber zunächst muss unsere Aufmerksamkeit der unmittelbaren... Plage gelten.\n\n<Koro schleudert den sich krümmenden Saurok HART gegen den Felsen.>\n\nFlüchtlingsgruppen aus dem Tempel sind auf dem Weg zu einem Lager im Norden, doch sie werden von Saurok angegriffen. Helft mir, die nächste Gruppe zum Lager zu bringen, dann entscheiden wir über unser weiteres Vorgehen.", sourceObjective = "Helft Koro Nebelgänger, eine Gruppe Flüchtlinge vom Tempel des Roten Kranichs zum Refugium der Kranichschwingen zu eskortieren. Sprecht vor Beginn zuerst mit Koro.", completion = "Danke, {name}. Ohne Eure Hilfe hätten wir es nicht geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[30270] = { id = 30270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blenden der Flussklingen", description = "\"Ein Falke mit Kappe fängt keine Beute.\"\n\nDas ist eines der ersten Mantras, die wir jungen Mönchen im Tempel beibringen. Es bedeutet, dass sogar ein Gegner, der so schnell und tödlich wie ein Falke ist, neutralisiert werden kann, indem man ihn seiner Sinne beraubt.\n\nDie Saurok verfügen in der ganzen Region über Späher, die ihren Raubzügen als Augen dienen.\n\nEs wird Zeit, dass wir ihnen die Augen ausstechen, meint Ihr nicht auch?", sourceObjective = "Tötet 8 Wegelagerer der Flussklingen in der Umgebung des Refugiums der Kranichschwingen.", completion = "Gut gemacht. Ich wünschte nur, ich hätte Euch begleiten können...\n\nDas Blut auf diesen Handlappen ist nicht mein eigenes, wisst Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[30271] = { id = 30271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shapokalypse", sourceObjective = "Tötet Sha in der Nähe von 10 hoffnungslosen Mönchen oder Akolythen, um sie zu inspirieren.", progress = "Haltet nach Kranichschwingen-Pandaren Ausschau, die der Verzweiflung anheimfallen, und erschlagt Sha in ihrer Nähe, während ich Euch unterstütze!", completion = "Ehrlich gesagt bin ich ein wenig überrascht, dass das funktioniert hat.\n\nPandaria erweist sich als Land, in dem die Grenze zwischen Metapher und Realität verschwommen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[30272] = { id = 30272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regen schlagen", description = "Was den Teil \"auf den Regen einschlagen\" angeht... Nun, manchmal muss man es einfach tun.\n\n\"Hoffnung ist die Sonne jenseits eines stürmischen Himmels - stets im Herzen, aber dem Auge verborgen.\"\n\nDas aus dem Tempel strömende Sha scheint kein Ende zu nehmen. Aber um hinter den Schleier der Verzweiflung zu sehen, müsst Ihr ihn zerschneiden.\n\nMit ein wenig Glück findet Ihr hinter den Wolken den Sonnenschein...", sourceObjective = "Tötet 18 Spuke der Verzweiflung beim Tempel des Roten Kranichs.", completion = "Wisst Ihr was, {name}? Wir geben ein ziemlich gutes Team ab!", sourceObjectiveStatus = "unverified-source-field" }
quests[30273] = { id = 30273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Haus des Roten Kranichs", sourceObjective = "Begebt Euch in den Keller des Tempels des Roten Kranichs und besiegt das Sha der Verzweiflung.", completion = "Ihr habt das Sha der Verzweiflung bezwungen. Mein Orden wird sich darum kümmern, hier aufzuräumen.\n\nWie es scheint, ist die Zeit gekommen, sich den Konsequenzen von Shaohaos Entscheidungen zu stellen.\n\nDieser Konflikt hat sich über Jahrtausende hinweg angebahnt - die Ankunft Eures Volkes war lediglich der Stein, der die Lawine ins Rollen gebracht hat. Wie dem auch sei, Eure Hilfe wird nötig sein, wenn Pandaria überleben soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[30274] = { id = 30274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die arkane Oubliette", description = "Ein Mitglied der Allianz? Hier? Elune sei gepriesen.\n\nMein Trupp ist auf ein Hindernis gestoßen. Wir haben mit ein paar alten Texten, die wir auf die Zeit vor Azsharas Herrschaft datiert haben, ein Portal zu diesem Land geöffnet.\n\nUnglücklicherweise waren die Koordinaten auf den Tafeln geschützt, und so lieferte uns das Portal, das uns zu unserem Ziel bringen sollte, in dieser Oubliette ab.\n\nWir sind hier schon seit Tagen gefangen, und das Portal zehrt langsam an unserer Energie, um sich selbst zu versorgen.\n\nKönnt Ihr die Fesseln in der Nähe suchen, die die Oubliette binden, und sie deaktivieren?", sourceObjective = "Sucht und deaktiviert 3 Fesseln der Oubliette.", completion = "Fabelhaft! Euer Zeitgefühl war einwandfrei. Noch ein Tag da drin und wir hätten uns wahrscheinlich in Nichts aufgelöst.\n\nJetzt können wir unsere Suche nach den Teichen der Jugend fortsetzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[30275] = { id = 30275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gigantismus", description = "Wie konnte dieser Krokilisk so groß werden?\n\nKlar, es gibt Gerüchte von sehr alten Krokilisken, die zu einer enormen Größe wachsen... aber dieses Weibchen ist höchstens 12 Jahre alt.\n\nVielleicht kann jemand in Neu-Cifera mehr über die Sache herausfinden.", sourceObjective = "Bringt den riesigen Krokiliskenschwanz zu Yan in Neu-Cifera im Tal der Vier Winde.", progress = "Was habt Ihr denn da?", completion = "Dieser Schwanz stammt von einem Krokilisken? Seltsam, so weit flussaufwärts gibt es nicht besonders viele Krokis.\n\nIst Euch das gigantische Obst und Gemüse aufgefallen, das unsere Bauern anpflanzen? Dieser Krokilisk ist aus dem gleichen Grund so groß geworden - es ist irgendetwas im Wasser.\n\nWas das ist, wissen wir nicht... aber wir sehen es als ein großes Glück an. Riesiges Gemüse ist eine tolle Sache. Ein riesiger Krokilisk dann und wann ist bloß eine Nebenerscheinung.", sourceObjectiveStatus = "unverified-source-field" }
quests[30277] = { id = 30277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die bröckelnde Halle", description = "In den Guo-Lai-Hallen wurde jenseits der Statuenhalle ein uraltes Moguartefakt entdeckt. Wir haben schon mehrfach versucht, das Artefakt zu bergen, hatten aber bisher keinen Erfolg.\n\nDieses Artefakt darf auf keinen Fall in die Hände der Shao-Tien fallen. Jemand muss dieses Artefakt bergen - und zwar schnell.\n\nKann ich auf Euch zählen?", sourceObjective = "Bergt das uralte Guo-Lai-Artefakt.", progress = "Habt Ihr das Artefakt schon bergen können?", completion = "Wenn alle anderen scheitern, seid Ihr zur Stelle. Das gefällt mir so an Euch.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30278] = { id = 30278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE FOR PROGRESSION" }
quests[30279] = { id = 30279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE FOR PROGRESSION" }
quests[30280] = { id = 30280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Röhren aus der Tiefe", description = "Aus den Guo-Lai-Hallen dringt ein mächtiges Röhren. Die Mogu haben dort irgendeine uralte Bestie zum Leben erweckt. Und sie werden sie wohl schon bald auf meine Männer loslassen.\n\nIch möchte, dass Ihr in die Halle der Schlange eindringt und diese Bestie unschädlich macht, bevor die Mogu sie gegen uns einsetzen. Mit einer solch gefährlichen und bedeutenden Aufgabe kann ich niemanden außer Euch beauftragen.", sourceObjective = "Tötet Milau.", completion = "Euch ist gelungen, was selbst mir kaum möglich gewesen wäre. Demütig zolle ich Eurer Stärke Respekt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30281] = { id = 30281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leises Anschleichen", description = "<Er lehnt sich vor und zeichnet etwas, was nur einen Mogu darstellen kann, zeigt in Richtung des Sees im Westen, zieht die stumpfe Seite seines Dolches über seine Kehle und schaut Euch erwartungsvoll an. Es scheint, als wolle er, dass Ihr die Mogu am Weißblütensee tötet.>", sourceObjective = "Tötet 6 Shao-Tien-Mogu am Weißblütensee.", sourceObjectiveStatus = "unverified-source-field" }
quests[30282] = { id = 30282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Dreck wegbrennen", description = "Die Mogu haben ihre dreckigen Banner rund um den See im Westen gehisst, um dieses Gebiet als ihr Territorium zu markieren. Nehmt diese Fackel und zeigt ihnen, was wir von ihren Bannern halten.", sourceObjective = "Verbrennt 10 Shao-Tien-Banner.", sourceObjectiveStatus = "unverified-source-field" }
quests[30283] = { id = 30283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerschlagende Argumente", description = "Manchmal tun mir diese Mogu nachgerade leid... Vielleicht reißen sie anderen Völkern nur deshalb die Seelen heraus, weil sie selbst Probleme mit ihren Familien zu Hause haben? Vielleicht sollten wir mehr Verständnis für den Ursprung ihrer Gewaltbereitschaft aufbringen?\n\nOder wir zerschlagen einfach ihre seelenraubenden Ritualobjekte da unten am See. Das würde mir persönlich ja viel mehr Spaß bringen.", sourceObjective = "Zerstört die Shao-Tien-Ritualstatuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30284] = { id = 30284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tausend spitze Zähnchen", description = "Das Wasser hat heute vor Gefahren nur so gebrodelt! Eine Art schwärmende, fleischfressende Fischpest hat sich in unserem See breitgemacht! Ein abscheulicher Anblick. Und das, wo ich gerade dabei war, mich vollständig zu entkleiden, um mich meinen täglichen Wasserübungen hinzugeben!\n\nIhr seid doch geübt darin, alle möglichen Kreaturen zu entsorgen, nicht wahr? Würdet Ihr also vielleicht so freundlich sein, Eure Fertigkeiten zu nutzen, um allen schwimmbegeisterten Pandaren einen Gefallen zu tun?\n\nDas wäre eine wirklich noble Tat für die Allgemeinheit - und insbesondere für mich.", sourceObjective = "Tötet 9 Messerzahnschwärmer.", sourceObjectiveStatus = "unverified-source-field" }
quests[30285] = { id = 30285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherberichte der Wukao", description = "Nach dem Angriff sind einige Späherberichte da draußen geblieben, die wir noch nicht eingesehen haben. Mit etwas Glück befinden sie sich noch im Dorf, aber vielleicht sind sie auch schon den Mogu in die Hände gefallen.\n\nWenn Ihr mir alle Späherberichte zurückbringt, die Ihr finden könnt, würdet Ihr mir einen großen Gefallen tun. Die Mogu dürfen nichts über unsere Stellungen oder unsere gefundenen Artefakte erfahren. Dann wären nämlich die Männer in einer noch viel größeren Gefahr.", sourceObjective = "Holt 3 Wukaospäherberichte.", sourceObjectiveStatus = "unverified-source-field" }
quests[30286] = { id = 30286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Enge getrieben", description = "Viele Dorfbewohner sind verängstigt und in die Enge getrieben. Ihr müsst ihnen zu Hilfe eilen und sie beschützen.\n\nBitte beeilt Euch und rettet so viele von ihnen wie möglich!", sourceObjective = "Rettet 6 in die Enge getriebene Dorfbewohner von Nebelhauch.", sourceObjectiveStatus = "unverified-source-field" }
quests[30287] = { id = 30287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu keine guten Gäste", description = "Leven hat Rook hierher geschickt, um Mogu aufzuhalten. Sind aber mehr Mogu als Rook töten kann.\n\nHelft Ihr? Rook erzählt Leven auch von Eurer Hilfe. Versprochen.", sourceObjective = "Tötet 6 Shao-Tien-Angreifer in Nebelhauch.", sourceObjectiveStatus = "unverified-source-field" }
quests[30288] = { id = 30288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es brennt... schon wieder!", description = "Ich weiß nicht, ob Ihr es bemerkt habt, aber meine Stadt brennt... schon wieder.\n\nWir haben überall Wassereimer im Ort, aber niemanden, der die Feuer löschen kann. Bitte helft uns!", sourceObjective = "Nutzt die Wassereimer in Nebelhauch, um 60 Feuer zu löschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[30289] = { id = 30289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiung der gestohlenen Seelen", description = "Mogu stehlen Seelen von Leuten! Lassen sie böse Dinge tun.\n\nAber nicht die Leute töten, sondern die Mogu. Dann vergessen die Leute die Verstandklauerei der Mogu und machen keine bösen Dinge mehr. Ihr solltet den Leuten helfen. So wie Rook.", sourceObjective = "Befreit 6 besessene Wachen, indem Ihr die Mogu tötet, die deren Gedanken steuern.", sourceObjectiveStatus = "unverified-source-field" }
quests[30290] = { id = 30290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steingebundene Mörder", description = "Mogusteinhundkreaturen jagen Dorfbewohner und tun ihnen weh. Rook wollte sie zerschmettern. Aber sie sind zu schnell.\n\nKönnt Ihr helfen und auch welche zerschmettern?", sourceObjective = "Tötet 8 steingebundene Qilen.", sourceObjectiveStatus = "unverified-source-field" }
